INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G8.NUMBER.INTEGERS.INT_IDENTIFY', 'MATH.G8.NUMBER.INTEGERS', 'mathematics', 8, 'Identify integers and use a sign for a situation above or below zero', ARRAY['MATH.G8.NUMBER.INTEGERS.a']::text[], 'The child sorts numbers into integers and non-integers (fractions and decimals are not integers), and writes a real situation as a signed integer: 3 floors below the ground as -3, a loss of 200 shillings as -200, 5 degrees above zero as +5.', '["which are integers","write the situation as an integer","the opposite of","zero is which"]'::jsonb, '["recall","representation"]'::jsonb, ARRAY['G6_INTEGERS_INTRO']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G8.NUMBER.INTEGERS.INT_ORDER_COMPARE', 'MATH.G8.NUMBER.INTEGERS', 'mathematics', 8, 'Compare and order integers, including negative ones', ARRAY['MATH.G8.NUMBER.INTEGERS.a', 'MATH.G8.NUMBER.INTEGERS.b']::text[], 'The child puts integers in order from smallest to largest and uses < and > between them, knowing that below zero the number further from zero is the smaller one (-9 < -2), and every negative number is smaller than every positive number and zero.', '["which is smaller","order from smallest","put < or >","why is this wrong"]'::jsonb, '["reasoning"]'::jsonb, ARRAY['G6_INTEGERS_INTRO']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G8.NUMBER.INTEGERS.INT_NUMBER_LINE', 'MATH.G8.NUMBER.INTEGERS', 'mathematics', 8, 'Represent integers on a number line', ARRAY['MATH.G8.NUMBER.INTEGERS.b']::text[], 'The child draws a number line with zero, equal steps and negative numbers to the left, marks given integers on it, and reads the integer at a marked point, including on a vertical line (floors, depths, heights above sea level).', '["mark the integers","which number is at the arrow","complete the number line","a vertical number line"]'::jsonb, '["representation"]'::jsonb, ARRAY['G6_INTEGERS_INTRO']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G8.NUMBER.INTEGERS.INT_ADD_SUB_LINE', 'MATH.G8.NUMBER.INTEGERS', 'mathematics', 8, 'Add and subtract integers by moving on a number line', ARRAY['MATH.G8.NUMBER.INTEGERS.c']::text[], 'The child starts at the first integer and moves right to add a positive number and left to subtract one, crossing zero without missing a step, and gives the integer reached: 3 - 7 = -4, -2 + 6 = 4, -5 - 3 = -8.', '["the lift goes down","start at, move","sum on the number line","what is -3 + 5"]'::jsonb, '["procedure","representation"]'::jsonb, ARRAY['G6_INTEGERS_ADD_SUB', 'G6_INTEGERS_INTRO']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G8.NUMBER.INTEGERS.INT_DIFFERENCE', 'MATH.G8.NUMBER.INTEGERS', 'mathematics', 8, 'Find the difference between two integers across zero', ARRAY['MATH.G8.NUMBER.INTEGERS.c']::text[], 'The child finds how far apart two integers are (a rise in temperature from -4 to 9, a height above sea level and a depth below it) by counting up to zero and then on, or by subtracting the smaller from the larger with signs: 9 - (-4) = 13.', '["how many degrees warmer","height from the bottom to the top","how far apart","find the mistake"]'::jsonb, '["procedure","reasoning"]'::jsonb, ARRAY['G6_INTEGERS_ADD_SUB', 'G6_INTEGERS_INTRO']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G8.NUMBER.INTEGERS.INT_COMBINED_CONTEXT', 'MATH.G8.NUMBER.INTEGERS', 'mathematics', 8, 'Use integer operations for balances and repeated changes in real life', ARRAY['MATH.G8.NUMBER.INTEGERS.c']::text[], 'The child keeps a running total of money in and out (a minus sign means money out), starting from the opening balance, and handles a change repeated over several steps: a fall of 3 m a month for 4 months is a change of -12 m, and a total change of -18 degrees over 6 hours is -3 degrees an hour.', '["balance on Friday","change each hour","level after some months","how many months until"]'::jsonb, '["procedure","modelling"]'::jsonb, ARRAY['G6_INTEGERS_ADD_SUB', 'G7_INTEGERS_MUL_DIV']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G8.NUMBER.FRACTIONS.FRAC_ORDER_OF_OPERATIONS', 'MATH.G8.NUMBER.FRACTIONS', 'mathematics', 8, 'Work out combined operations on fractions in the correct order', ARRAY['MATH.G8.NUMBER.FRACTIONS.a']::text[], 'The child works out a combined question such as 3/4 - 1/2 ÷ 2/3 by dividing or multiplying before adding or subtracting, turns the divisor upside down to divide, and simplifies the answer.', '["work out","which step has the mistake","which is done first","simplest form"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G8_FRACTIONS_COMBINED']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G8.NUMBER.FRACTIONS.FRAC_BRACKETS_AND_OF', 'MATH.G8.NUMBER.FRACTIONS', 'mathematics', 8, 'Work out combined operations on fractions with brackets and "of"', ARRAY['MATH.G8.NUMBER.FRACTIONS.a']::text[], 'The child works out the bracket first, treats "of" as multiplication done before adding or subtracting, and finishes in the right order: (1/2 + 1/3) × 3/5 = 1/2, and 2/3 of 3/4 + 1/4 = 3/4.', '["work out the bracket","of means","which step first","simplify"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G8_FRACTIONS_COMBINED']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G8.NUMBER.FRACTIONS.FRAC_MIXED_COMBINED', 'MATH.G8.NUMBER.FRACTIONS', 'mathematics', 8, 'Work out combined operations that include mixed numbers', ARRAY['MATH.G8.NUMBER.FRACTIONS.a']::text[], 'The child changes each mixed number to an improper fraction before multiplying or dividing, keeps whole parts and fractions together when adding, and writes the final answer as a mixed number in its simplest form: 1 1/2 × 2/3 + 1/4 = 1 1/4.', '["mixed numbers in a combined question","change to improper fractions","answer as a mixed number","find the mistake"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G8_FRACTIONS_COMBINED']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G8.NUMBER.FRACTIONS.FRAC_REST_OF_WHOLE', 'MATH.G8.NUMBER.FRACTIONS', 'mathematics', 8, 'Find the part left after fractions of the same whole are used', ARRAY['MATH.G8.NUMBER.FRACTIONS.a', 'MATH.G8.NUMBER.FRACTIONS.b']::text[], 'The child adds the fractions used of one whole (a shamba, a school day), takes the sum from 1, and finds that fraction of the whole quantity in the unit asked: a day of 8 hours with 1/4, 1/3 and 1/6 used leaves 1/4 of 480 minutes = 120 minutes.', '["how many acres are left","minutes for clubs","what fraction is left","the rest is"]'::jsonb, '["procedure","modelling"]'::jsonb, ARRAY['G8_FRACTIONS_COMBINED']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G8.NUMBER.FRACTIONS.FRAC_OF_REMAINDER', 'MATH.G8.NUMBER.FRACTIONS', 'mathematics', 8, 'Find a fraction of what is left, step by step', ARRAY['MATH.G8.NUMBER.FRACTIONS.b']::text[], 'The child finds what is left after the first fraction, then takes the second fraction of that remainder (not of the whole): a tank of 6,000 litres is 3/4 full, a school uses 1/3 of the water, so 4,500 - 1,500 = 3,000 litres remain.', '["what is left after","a fraction of the rest","how much was used","water left in the tank"]'::jsonb, '["procedure","modelling"]'::jsonb, ARRAY['G8_FRACTIONS_COMBINED']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G8.NUMBER.FRACTIONS.FRAC_SHOPPING_CONTEXT', 'MATH.G8.NUMBER.FRACTIONS', 'mathematics', 8, 'Use operations on fractions for buying, pricing and sharing', ARRAY['MATH.G8.NUMBER.FRACTIONS.b']::text[], 'The child works out the cost of a fraction of a kilogram or metre, how many fractional pieces or packets can be cut or filled, and shares an amount by fractions, choosing to multiply or divide from the story: 3/4 kg at 120 shillings a kg costs 90 shillings; 6 m cut into 3/4 m pieces gives 8 pieces.', '["cost of a fraction of a kg","how many pieces","packets of","what each gets"]'::jsonb, '["modelling"]'::jsonb, ARRAY['G8_FRACTIONS_COMBINED']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G8.NUMBER.DECIMALS.FRACTION_TO_DECIMAL', 'MATH.G8.NUMBER.DECIMALS', 'mathematics', 8, 'Convert a fraction to a decimal by division', ARRAY['MATH.G8.NUMBER.DECIMALS.a']::text[], 'The child divides the numerator by the denominator (adding zeros after the point as needed) or makes the denominator a power of 10, and writes the decimal with each digit in its place: 3/8 = 0.375, 1/20 = 0.05, 7/4 = 1.75.', '["fraction to decimal","by long division","make the denominator 100","mixed number to decimal"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G6_FRACTIONS_DECIMALS', 'G8_RECURRING_DECIMALS']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G8.NUMBER.DECIMALS.RECURRING_IDENTIFY', 'MATH.G8.NUMBER.DECIMALS', 'mathematics', 8, 'Identify recurring decimals and show the repeating digits', ARRAY['MATH.G8.NUMBER.DECIMALS.b']::text[], 'The child sorts decimals into terminating and recurring, marks the repeating block (0.272727... has 27 repeating), and explains that a fraction in its simplest form recurs when its denominator has a prime factor other than 2 and 5: 5/12 recurs, 3/40 stops.', '["recurring or not","which digits repeat","why does it never stop","will this fraction stop"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY['G8_RECURRING_DECIMALS']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G8.NUMBER.DECIMALS.RECURRING_TO_FRACTION', 'MATH.G8.NUMBER.DECIMALS', 'mathematics', 8, 'Convert a recurring decimal to a fraction', ARRAY['MATH.G8.NUMBER.DECIMALS.c']::text[], 'The child lets x be the decimal, multiplies by 10 for one repeating digit or by 100 for two, subtracts x so the repeats cancel, divides and simplifies: 0.2727... gives 99x = 27, so x = 27/99 = 3/11.', '["let x =","multiply by 10 or 100","write as a fraction in simplest form","which fraction equals"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G8_RECURRING_DECIMALS']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G8.NUMBER.DECIMALS.ROUND_DECIMAL_PLACES', 'MATH.G8.NUMBER.DECIMALS', 'mathematics', 8, 'Round a decimal to a given number of decimal places', ARRAY['MATH.G8.NUMBER.DECIMALS.d']::text[], 'The child counts the decimal places from the point, looks at the next digit, rounds up when it is 5 or more (carrying through a 9), and keeps the zeros the question asks for: 2.9765 to 2 d.p. is 2.98, 3.997 to 2 d.p. is 4.00.', '["round to 1, 2 or 3 decimal places","a price to the nearest cent","a measurement","which is correct"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G6_FRACTIONS_DECIMALS', 'G8_DECIMALS_COMBINED']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G8.NUMBER.DECIMALS.SIGNIFICANT_FIGURES', 'MATH.G8.NUMBER.DECIMALS', 'mathematics', 8, 'Write a number to a given number of significant figures', ARRAY['MATH.G8.NUMBER.DECIMALS.e']::text[], 'The child counts significant figures from the first non-zero digit, rounds at the last one kept, and keeps zeros that hold the place in a whole number: 48,273 to 2 s.f. is 48,000; 0.004567 to 2 s.f. is 0.0046.', '["correct to 2 or 3 significant figures","how many significant figures","a population or a mass","find the mistake"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G8_STANDARD_FORM']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G8.NUMBER.DECIMALS.STANDARD_FORM', 'MATH.G8.NUMBER.DECIMALS', 'mathematics', 8, 'Write numbers in standard form and work with them', ARRAY['MATH.G8.NUMBER.DECIMALS.f']::text[], 'The child writes a number as A × 10 to a power with A from 1 up to but not including 10, the power counting the places the point moves (positive for large numbers, negative for small): 45,000 = 4.5 × 10⁴, 0.0032 = 3.2 × 10⁻³; when multiplying, multiplies the front numbers, adds the powers and adjusts so A stays below 10.', '["write in standard form","write as an ordinary number","which step has the mistake","multiply in standard form"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G8_STANDARD_FORM']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G8.NUMBER.DECIMALS.DEC_COMBINED_OPERATIONS', 'MATH.G8.NUMBER.DECIMALS', 'mathematics', 8, 'Work out combined operations on decimals in the correct order', ARRAY['MATH.G8.NUMBER.DECIMALS.g']::text[], 'The child works brackets, then multiplication and division, then addition and subtraction, places the point in a product by counting decimal places, and lines up points when adding: 2.5 + 0.4 × 1.3 = 3.02.', '["work out","brackets first","where does the point go","which step has the mistake"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G8_DECIMALS_COMBINED']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G8.NUMBER.DECIMALS.DEC_REAL_LIFE', 'MATH.G8.NUMBER.DECIMALS', 'mathematics', 8, 'Apply decimals to money, measures and profit in real life', ARRAY['MATH.G8.NUMBER.DECIMALS.h']::text[], 'The child sets up a real problem with decimals (cloth at shillings a metre, items at shillings and cents, change from a note), works the cost of one, the cost of all, and the profit or change in the right order.', '["profit altogether","change from a note","cost of the cloth","how much each"]'::jsonb, '["modelling"]'::jsonb, ARRAY['G8_DECIMALS_COMBINED']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G8.NUMBER.SQUARES_AND_SQUARE_ROOTS.SQUARE_FROM_TABLE', 'MATH.G8.NUMBER.SQUARES_AND_SQUARE_ROOTS', 'mathematics', 8, 'Find the square of a number from a table of squares', ARRAY['MATH.G8.NUMBER.SQUARES_AND_SQUARE_ROOTS.a']::text[], 'The child reads the square of a number from 1 to 10 from the table (row for the first two figures, column for the third), and for a number outside the table writes it as a table number times 10, 100 or 0.1 and multiplies the table value by the square of that factor: 43.6² = 4.36² × 100 = 1,901.', '["read from the table","a number 10 times bigger","a number smaller than 1","which is the square"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G8_SQUARES_TABLES']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G8.NUMBER.SQUARES_AND_SQUARE_ROOTS.SQUARE_AREA_COST', 'MATH.G8.NUMBER.SQUARES_AND_SQUARE_ROOTS', 'mathematics', 8, 'Use the square of a number for the area of a square and its cost', ARRAY['MATH.G8.NUMBER.SQUARES_AND_SQUARE_ROOTS.a']::text[], 'The child squares the side (not doubles it, not multiplies by 4) to get the area of a square floor, plot or tile, keeps the units in square metres, and multiplies by the price per square metre.', '["cost of tiling a square room","area of a square plot","how many square metres","cost per square metre"]'::jsonb, '["modelling"]'::jsonb, ARRAY['G8_SQUARES_TABLES']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G8.NUMBER.SQUARES_AND_SQUARE_ROOTS.ROOT_FROM_TABLE', 'MATH.G8.NUMBER.SQUARES_AND_SQUARE_ROOTS', 'mathematics', 8, 'Find the square root of a number from tables', ARRAY['MATH.G8.NUMBER.SQUARES_AND_SQUARE_ROOTS.b']::text[], 'The child pairs the digits from the decimal point to choose the right table (from 1 to 10 or from 10 to 100), reads the root, and moves the point one place for every pair: √4,500 = √45 × 10 = 67.08, √0.45 = √45 ÷ 10 = 0.6708.', '["read the root from the table","a number 100 times bigger","which table to use","to 2 decimal places"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G8_SQUARES_TABLES']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G8.NUMBER.SQUARES_AND_SQUARE_ROOTS.ROOT_BETWEEN_SQUARES', 'MATH.G8.NUMBER.SQUARES_AND_SQUARE_ROOTS', 'mathematics', 8, 'Place a square root between two whole numbers and check a table value', ARRAY['MATH.G8.NUMBER.SQUARES_AND_SQUARE_ROOTS.b']::text[], 'The child finds the perfect squares on either side (49 < 55 < 64, so √55 is between 7 and 8), says which end it is nearer, and uses this to check that a value read from the table is sensible.', '["between which two whole numbers","why is that correct","is the table value sensible","nearer to which"]'::jsonb, '["reasoning"]'::jsonb, ARRAY['G8_SQUARES_TABLES']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G8.NUMBER.SQUARES_AND_SQUARE_ROOTS.SQUARE_BY_CALCULATOR', 'MATH.G8.NUMBER.SQUARES_AND_SQUARE_ROOTS', 'mathematics', 8, 'Work out squares of numbers with a calculator', ARRAY['MATH.G8.NUMBER.SQUARES_AND_SQUARE_ROOTS.c']::text[], 'The child keys the number and the x² key (or the number times itself), reads the full display, writes the answer with its units, and checks the size by estimating: 3.45² = 11.9025, about 3.5 × 3.5 = 12.', '["use a calculator","area of a square tile","estimate first","square of a negative number"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G8_SQUARES_TABLES']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G8.NUMBER.SQUARES_AND_SQUARE_ROOTS.ROOT_BY_CALCULATOR', 'MATH.G8.NUMBER.SQUARES_AND_SQUARE_ROOTS', 'mathematics', 8, 'Work out square roots with a calculator and round them', ARRAY['MATH.G8.NUMBER.SQUARES_AND_SQUARE_ROOTS.c']::text[], 'The child uses the square root key, rounds the display to the decimal places asked, and uses a root to find the side of a square from its area: a plot of 200 m² has a side of 14.1 m to 1 d.p.', '["side of a square plot","use the square root key","to 1 decimal place","check by squaring"]'::jsonb, '["procedure","modelling"]'::jsonb, ARRAY['G8_SQUARES_TABLES']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_.RATE_PER_UNIT', 'MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_', 'mathematics', 8, 'Identify a rate and work it out as an amount for one unit', ARRAY['MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_.a', 'MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_.b']::text[], 'The child names a rate in words with its two units (km per hour, litres per minute, shillings per kg), works it out by dividing the amount by the number of units, and compares rates (best buy) by finding each one per single unit.', '["rate in km per hour","price per kg","which shop is cheapest per kg","words per minute"]'::jsonb, '["procedure","reasoning"]'::jsonb, ARRAY['G8_RATIO_PROPORTION']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_.RATE_USE', 'MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_', 'mathematics', 8, 'Use a rate to find an amount or a time', ARRAY['MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_.b']::text[], 'The child finds the rate for one unit and multiplies to get the amount for several units, or divides what is still needed by the rate to get the time: 120 km in 3 hours is 40 km an hour, so 5 hours gives 200 km; a tank needing 600 more litres at 40 litres a minute takes 15 minutes.', '["at the same rate","how long to fill","how far in","litres still needed"]'::jsonb, '["modelling"]'::jsonb, ARRAY['G8_RATIO_PROPORTION']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_.FRACTION_AS_RATIO', 'MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_', 'mathematics', 8, 'Express fractions and quantities as ratios in their simplest form', ARRAY['MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_.c']::text[], 'The child writes a part-part ratio from a fraction of a whole (2/5 of a class are girls gives girls : boys = 2 : 3), writes a ratio in the order the question gives, and simplifies it by the HCF.', '["fraction to ratio","boys to girls","which class has the ratio","simplest form"]'::jsonb, '["representation"]'::jsonb, ARRAY['G8_RATIO_PROPORTION', 'G6_RATIOS']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_.RATIO_COMPARE', 'MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_', 'mathematics', 8, 'Compare two or more ratios', ARRAY['MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_.d']::text[], 'The child compares ratios by making one term the same (the same amount of sand) or by changing each to a fraction of its whole, never by comparing one term alone: cement : sand 2 : 5 has less cement per bag of sand than 3 : 7.', '["which mix has more","which class has the bigger share","are the ratios equal","why"]'::jsonb, '["reasoning"]'::jsonb, ARRAY['G8_RATIO_PROPORTION', 'G6_RATIOS']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_.RATIO_SHARE', 'MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_', 'mathematics', 8, 'Divide a quantity in a given ratio', ARRAY['MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_.e']::text[], 'The child adds the parts, finds the value of one part, and multiplies by each share; when one share is known instead of the total, finds one part from it first: 9,000 shillings in 2 : 3 : 4 gives 1,000 a part, so 2,000, 3,000 and 4,000.', '["share in the ratio","how much more than","one share is known","how many altogether"]'::jsonb, '["procedure","modelling"]'::jsonb, ARRAY['G8_RATIO_PROPORTION', 'G6_RATIOS']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_.RATIO_WORK_OUT', 'MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_', 'mathematics', 8, 'Work out the ratio of two quantities in the same units', ARRAY['MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_.f']::text[], 'The child changes both quantities to the same unit, writes them in the order asked and simplifies, including to the form 1 : n, and finds a missing term of equal ratios: 25 cm to 3 m is 25 : 300 = 1 : 12.', '["ratio of the short to the long piece","in the form 1 : n","missing term","change units first"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G8_RATIO_PROPORTION']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_.RATIO_INCREASE_DECREASE', 'MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_', 'mathematics', 8, 'Increase or decrease a quantity in a given ratio', ARRAY['MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_.g']::text[], 'The child reads the ratio as new : old, divides the quantity by the old number and multiplies by the new, and checks that an increase gives more and a decrease less: 600 g increased in the ratio 5 : 3 is 1,000 g.', '["increase in the ratio","decrease the rent","new fare","why is that wrong"]'::jsonb, '["procedure","reasoning"]'::jsonb, ARRAY['G8_RATIO_PROPORTION']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_.PERCENT_CHANGE', 'MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_', 'mathematics', 8, 'Work out the percentage increase or decrease of a quantity', ARRAY['MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_.h']::text[], 'The child finds the change, divides it by the original amount (not the new one) and multiplies by 100: a fare going from 80 to 100 shillings is a 25% increase.', '["percentage increase","percentage decrease","which calculation","which year had the greatest increase"]'::jsonb, '["procedure","reasoning"]'::jsonb, ARRAY['G8_PERCENTAGE_CHANGE']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_.PERCENT_CHANGE_REVERSE', 'MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_', 'mathematics', 8, 'Find the amount before a percentage change', ARRAY['MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_.h']::text[], 'The child writes the new amount as a percentage of the original (after a 20% increase it is 120%), finds 1% and then 100%: a price of 960 shillings after a 20% rise was 800 shillings, not 960 minus 20% of 960.', '["price before the rise","salary before the cut","which is the original","find the old price"]'::jsonb, '["procedure","reasoning"]'::jsonb, ARRAY['G8_PERCENTAGE_CHANGE']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_.PROPORTION_IDENTIFY', 'MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_', 'mathematics', 8, 'Identify direct and inverse proportion', ARRAY['MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_.i']::text[], 'The child imagines the first quantity doubling: if the second doubles it is direct proportion, if it halves it is inverse, and if there is no such rule it is neither.', '["direct, inverse or neither","which pair is inverse","what happens when it doubles","give an example"]'::jsonb, '["reasoning"]'::jsonb, ARRAY['G8_RATIO_PROPORTION']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_.PROPORTION_SOLVE', 'MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_', 'mathematics', 8, 'Work out direct and inverse proportion problems', ARRAY['MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_.j']::text[], 'The child uses the unitary method: for direct proportion finds one unit and multiplies; for inverse proportion finds the total (workers × days) and shares it: 6 workers take 10 days, so 4 workers take 60 ÷ 4 = 15 days.', '["how many days for","cost of","which row is wrong","more workers"]'::jsonb, '["procedure","modelling"]'::jsonb, ARRAY['G8_RATIO_PROPORTION']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.FACTORISE_HCF', 'MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS', 'mathematics', 8, 'Factorise an expression by taking out the highest common factor of the numbers', ARRAY['MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.a']::text[], 'The child finds the HCF of the coefficients and the number, writes it outside a bracket and what is left of each term inside, and checks by expanding: 12x + 18 = 6(2x + 3), not 3(4x + 6).', '["factorise fully","the number outside the bracket","which step has the mistake","length and width from the area"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G8_FACTORIZE_COMMON']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.FACTORISE_LETTERS', 'MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS', 'mathematics', 8, 'Factorise when the common factor includes a letter', ARRAY['MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.a']::text[], 'The child collects like terms first, then takes out the common letter with the common number, reducing the power inside the bracket: 3x² + 6x = 3x(x + 2), 4ab - 6a = 2a(2b - 3).', '["common factor with a letter","collect like terms first","factorise fully","check by expanding"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G8_FACTORIZE_COMMON']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.ALG_FRACTION_SIMPLIFY', 'MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS', 'mathematics', 8, 'Simplify an algebraic fraction', ARRAY['MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.b']::text[], 'The child divides every term of the top by the bottom, or factorises the top and cancels a common factor, never cancelling a number or letter that is only part of a sum: (6x + 9)/3 = 2x + 3, (4x + 8)/(x + 2) = 4.', '["simplify","which step has the mistake","can this be cancelled","factorise and cancel"]'::jsonb, '["procedure","reasoning"]'::jsonb, ARRAY['G8_FACTORIZE_COMMON', 'G8_LINEAR_EQ_ADV']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.ALG_FRACTION_ADD_SUB', 'MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS', 'mathematics', 8, 'Add and subtract algebraic fractions and use them in an equation', ARRAY['MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.b']::text[], 'The child writes each fraction over a common denominator (the LCM of the bottoms), changes each top to match, then adds or subtracts the tops, putting a bracket round a top that is subtracted; to solve, multiplies both sides by the common denominator and divides by what is left: x/3 + x/4 = 7 gives 7x/12 = 7, so x = 12.', '["add the fractions","why is this wrong","find x","subtract"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G8_LINEAR_EQ_ADV']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.SUBSTITUTE_POSITIVE', 'MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS', 'mathematics', 8, 'Evaluate an expression by substituting positive values', ARRAY['MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.c']::text[], 'The child replaces each letter with its value as a multiplication (3d with d = 4 is 3 × 4), keeps the fixed part, and works in the order of operations: F = 50 + 30d with d = 6 gives 230.', '["find F when","the fare for a distance","evaluate","the width from the length"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G7_EXPRESSIONS', 'G8_EXPAND_BRACKETS']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.SUBSTITUTE_NEGATIVE', 'MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS', 'mathematics', 8, 'Evaluate an expression with negative values and squares', ARRAY['MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.c']::text[], 'The child puts a negative value in brackets, squares the value (not the coefficient), knows a negative squared is positive and that taking away a negative adds: 3m² - 2n with m = -2, n = 5 gives 12 - 10 = 2.', '["evaluate with a negative value","which working is right","square a negative","take away a negative"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G8_EXPAND_BRACKETS']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G8.ALGEBR.LINEAR_EQUATIONS.FORM_SIMULTANEOUS', 'MATH.G8.ALGEBR.LINEAR_EQUATIONS', 'mathematics', 8, 'Form two linear equations in two unknowns from a story', ARRAY['MATH.G8.ALGEBR.LINEAR_EQUATIONS.a']::text[], 'The child names the two unknowns with letters and units, writes one equation for each fact in the story (each with its own total), and matches every number to the right letter: 3 mandazi and 2 chapati for 70 shillings is 3m + 2c = 70.', '["form two equations","which pair is right","which step has the mistake","more than, less than"]'::jsonb, '["modelling","representation"]'::jsonb, ARRAY['G8_SIMULTANEOUS_INTRO']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G8.ALGEBR.LINEAR_EQUATIONS.SOLVE_BY_SUBSTITUTION', 'MATH.G8.ALGEBR.LINEAR_EQUATIONS', 'mathematics', 8, 'Solve simultaneous equations by substitution', ARRAY['MATH.G8.ALGEBR.LINEAR_EQUATIONS.b']::text[], 'The child makes one unknown the subject of one equation (or uses one already given as y = ...), substitutes the whole expression in a bracket into the other equation, solves for the first unknown, then substitutes back to find the second and checks both equations.', '["solve by substitution","which step has the mistake","y is given in terms of x","check the answer"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G8_SIMULTANEOUS_INTRO']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G8.ALGEBR.LINEAR_EQUATIONS.SOLVE_BY_ELIMINATION', 'MATH.G8.ALGEBR.LINEAR_EQUATIONS', 'mathematics', 8, 'Solve simultaneous equations by elimination when one unknown has the same coefficient', ARRAY['MATH.G8.ALGEBR.LINEAR_EQUATIONS.c']::text[], 'The child sees that one unknown has the same number in front in both equations, subtracts the equations (or adds them when the terms are opposites) so that unknown cancels, divides by the coefficient that is left, and substitutes back for the other unknown.', '["solve by elimination","add or subtract","why does subtracting help","find x and y"]'::jsonb, '["procedure","reasoning"]'::jsonb, ARRAY['G8_SIMULTANEOUS_INTRO', 'G8_LINEAR_EQ_ADV']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G8.ALGEBR.LINEAR_EQUATIONS.ELIMINATION_MAKE_EQUAL', 'MATH.G8.ALGEBR.LINEAR_EQUATIONS', 'mathematics', 8, 'Multiply an equation to make the coefficients equal, then eliminate', ARRAY['MATH.G8.ALGEBR.LINEAR_EQUATIONS.c']::text[], 'The child multiplies every term of one (or both) equations, the right side too, by the number that makes the coefficients of one unknown equal, then eliminates as before: 2x + 3y = 12 and x + y = 5 becomes 2x + 2y = 10, so y = 2 and x = 3.', '["make the coefficients equal","multiply the second equation by","solve by elimination","which multiplier"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G8_SIMULTANEOUS_INTRO']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G8.ALGEBR.LINEAR_EQUATIONS.SIMULTANEOUS_IN_CONTEXT', 'MATH.G8.ALGEBR.LINEAR_EQUATIONS', 'mathematics', 8, 'Use simultaneous equations to solve real-life problems', ARRAY['MATH.G8.ALGEBR.LINEAR_EQUATIONS.d']::text[], 'The child forms two equations from a story (tickets, coins, animals and legs, prices), solves them by any method, and answers the question that was asked, with units, checking that the answer makes sense in the story.', '["price of one adult ticket","how many sh 10 coins","how many goats","cost of one item"]'::jsonb, '["modelling"]'::jsonb, ARRAY['G8_SIMULTANEOUS_INTRO']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G8.MEASUR.CIRCLES.CIRCUMFERENCE_RADIUS_DIAMETER', 'MATH.G8.MEASUR.CIRCLES', 'mathematics', 8, 'Work out the circumference of a circle from its radius or diameter', ARRAY['MATH.G8.MEASUR.CIRCLES.a']::text[], 'The child uses C = πd or C = 2πr, doubling a radius first, multiplying (never adding or dividing) by π, and gives the answer in the units of the length: a radius of 14 cm gives 2 × 22/7 × 14 = 88 cm.', '["circumference from the radius","why is this wrong","round a running track","with π = 22/7"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G9_ARC_LENGTH', 'G7_CIRCUMFERENCE']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G8.MEASUR.CIRCLES.CIRCUMFERENCE_DISTANCE', 'MATH.G8.MEASUR.CIRCLES', 'mathematics', 8, 'Use the circumference for distances travelled and laps', ARRAY['MATH.G8.MEASUR.CIRCLES.a']::text[], 'The child finds the distance for one turn or lap (the circumference), multiplies by the number of turns, divides a total distance by one lap to count laps, and changes cm to m when asked.', '["how far does the wheel travel","how many laps","distance in metres","how many turns"]'::jsonb, '["modelling"]'::jsonb, ARRAY['G9_ARC_LENGTH', 'G7_CIRCUMFERENCE']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G8.MEASUR.CIRCLES.ARC_LENGTH', 'MATH.G8.MEASUR.CIRCLES', 'mathematics', 8, 'Work out the length of an arc of a circle', ARRAY['MATH.G8.MEASUR.CIRCLES.b']::text[], 'The child writes the angle at the centre as a fraction of 360, finds the full circumference, and takes that fraction of it: an arc of 60° on a circle of radius 21 cm is 60/360 × 132 = 22 cm.', '["length of the arc","complete the table","which step has the mistake","the curved edge"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G9_ARC_LENGTH']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G8.MEASUR.CIRCLES.ARC_IN_CONTEXT', 'MATH.G8.MEASUR.CIRCLES', 'mathematics', 8, 'Find the angle from a situation and then the arc', ARRAY['MATH.G8.MEASUR.CIRCLES.b']::text[], 'The child works out the angle turned from the story (a minute hand turns 6° a minute, so 20 minutes is 120°), then finds that fraction of the circumference.', '["how far does the tip of the hand move","a swing seat","a curved road","a windscreen wiper"]'::jsonb, '["modelling"]'::jsonb, ARRAY['G9_ARC_LENGTH']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G8.MEASUR.CIRCLES.SECTOR_PERIMETER', 'MATH.G8.MEASUR.CIRCLES', 'mathematics', 8, 'Calculate the perimeter of a sector', ARRAY['MATH.G8.MEASUR.CIRCLES.c']::text[], 'The child adds the arc and the two straight edges, each a radius: a sector of radius 7 m and angle 90° has a perimeter of 11 + 7 + 7 = 25 m; for a half circle the straight edge is the diameter.', '["perimeter of the sector","fence round a garden bed","perimeter of a half circle","a slice of cake"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G9_ARC_LENGTH']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G8.MEASUR.CIRCLES.SECTOR_WORK_BACK', 'MATH.G8.MEASUR.CIRCLES', 'mathematics', 8, 'Find the radius from the perimeter of a half circle or sector', ARRAY['MATH.G8.MEASUR.CIRCLES.c']::text[], 'The child writes the perimeter in terms of r (a half circle has πr + 2r), collects the r terms and divides: a perimeter of 72 m gives (22/7 + 2)r = 72, so r = 14 m.', '["find the radius","perimeter is given","how wide is the plot","work back"]'::jsonb, '["procedure","reasoning"]'::jsonb, ARRAY['G9_ARC_LENGTH']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G8.MEASUR.AREA.AREA_CIRCLE_RADIUS', 'MATH.G8.MEASUR.AREA', 'mathematics', 8, 'Calculate the area of a circle and how it changes with the radius', ARRAY['MATH.G8.MEASUR.AREA.a']::text[], 'The child uses A = πr² with the radius (halving a diameter first), and explains that doubling the radius makes the area four times as big because the radius is used twice: a radius of 7 m gives 154 m², a radius of 14 m gives 616 m².', '["area of a circle","how many times as much","from the diameter","why"]'::jsonb, '["procedure","reasoning"]'::jsonb, ARRAY['G8_AREA_COMPOSITE', 'G7_AREA_CIRCLE']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G8.MEASUR.AREA.AREA_CIRCLE_COMPOSITE', 'MATH.G8.MEASUR.AREA', 'mathematics', 8, 'Find the area of shapes made from circles and rectangles', ARRAY['MATH.G8.MEASUR.AREA.a']::text[], 'The child splits a shape into circles, half circles and rectangles, finds each part with the right radius, and adds or subtracts: a path 7 m wide round a garden of radius 7 m has area π × 14² - π × 7² = 462 m².', '["area of the path","an arched window","a ring","area of glass"]'::jsonb, '["procedure","modelling"]'::jsonb, ARRAY['G8_AREA_COMPOSITE']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G8.MEASUR.AREA.SECTOR_AREA', 'MATH.G8.MEASUR.AREA', 'mathematics', 8, 'Work out the area of a sector of a circle', ARRAY['MATH.G8.MEASUR.AREA.b']::text[], 'The child takes θ/360 of the area of the whole circle (not of the circumference), and explains that the area is shared in the same fraction as the angle: a sprinkler reaching 14 m through 90° waters 1/4 of 616 = 154 m².', '["area watered","area of a slice","why is that right","fraction of the circle"]'::jsonb, '["procedure","reasoning"]'::jsonb, ARRAY['G9_ARC_LENGTH', 'G8_AREA_COMPOSITE']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G8.MEASUR.AREA.SECTOR_FIND_ANGLE', 'MATH.G8.MEASUR.AREA', 'mathematics', 8, 'Find the angle of a sector from its area', ARRAY['MATH.G8.MEASUR.AREA.b']::text[], 'The child divides the area of the sector by the area of the whole circle to get the fraction, then multiplies by 360: a light reaching 14 m and lighting 154 m² spreads through 154/616 × 360 = 90°.', '["through what angle","from the area lit","fraction to degrees","check"]'::jsonb, '["procedure","reasoning"]'::jsonb, ARRAY['G9_ARC_LENGTH']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G8.MEASUR.AREA.SA_CUBOID', 'MATH.G8.MEASUR.AREA', 'mathematics', 8, 'Work out the surface area of cubes and cuboids', ARRAY['MATH.G8.MEASUR.AREA.c']::text[], 'The child finds the three different faces (l × w, l × h, w × h), doubles each because there is one on each side, and adds: a box 5 cm by 4 cm by 3 cm has 2(20 + 15 + 12) = 94 cm²; a cube has six equal faces.', '["paper to cover a box","which carton needs the most card","which step has the mistake","a cube"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G8_SURFACE_AREA']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G8.MEASUR.AREA.SA_CUBOID_IN_CONTEXT', 'MATH.G8.MEASUR.AREA', 'mathematics', 8, 'Use surface area for real jobs with some faces left out', ARRAY['MATH.G8.MEASUR.AREA.c']::text[], 'The child decides which faces are covered (four walls and a ceiling, a box with no lid), takes away doors and windows, and divides by what one litre or one sheet covers.', '["painting a classroom","an open box","litres of paint","take away the windows"]'::jsonb, '["modelling"]'::jsonb, ARRAY['G8_SURFACE_AREA']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G8.MEASUR.AREA.SA_CYLINDER', 'MATH.G8.MEASUR.AREA', 'mathematics', 8, 'Work out the surface area of a cylinder, open or closed', ARRAY['MATH.G8.MEASUR.AREA.d']::text[], 'The child finds the curved side as the circumference times the height (2πrh), adds one circle for an open tank and two for a closed tin, and uses the radius (half the diameter): a closed tin of radius 7 cm and height 10 cm needs 440 + 308 = 748 cm².', '["metal for a tank with no lid","area of a label","a closed tin","from the diameter"]'::jsonb, '["procedure","modelling"]'::jsonb, ARRAY['G8_SURFACE_AREA']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G8.MEASUR.AREA.SA_TRIANGULAR_PRISM', 'MATH.G8.MEASUR.AREA', 'mathematics', 8, 'Determine the surface area of a triangular prism', ARRAY['MATH.G8.MEASUR.AREA.e']::text[], 'The child adds the two triangular ends (each half base times the straight-up height) and the three rectangles (each side of the triangle times the length): ends of 3, 4 and 5 cm with length 10 cm give 12 + 120 = 132 cm².', '["cloth for a tent","total surface area from a table","which step has the mistake","card for a prism"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G8_SURFACE_AREA']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G8.MEASUR.AREA.AREA_IRREGULAR_GRID', 'MATH.G8.MEASUR.AREA', 'mathematics', 8, 'Estimate the area of an irregular shape on a square grid', ARRAY['MATH.G8.MEASUR.AREA.f']::text[], 'The child counts whole squares, counts part squares as half each, adds, and multiplies by the area of one square when the grid is to scale: 20 whole and 10 part squares of 5 m by 5 m give 25 × 25 = 625 m².', '["area of a leaf","a plot on a scaled grid","which field is largest","part squares"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G8_AREA_COMPOSITE']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G8.MEASUR.MONEY.INTEREST_TERMS', 'MATH.G8.MEASUR.MONEY', 'mathematics', 8, 'Identify principal, interest, rate, time and amount', ARRAY['MATH.G8.MEASUR.MONEY.a']::text[], 'The child names the principal (the money saved or borrowed), the interest (the extra paid for it), the rate (per cent a year), the time and the amount (principal plus interest) in a story about a bank, SACCO or loan, and says who pays the interest.', '["which is the principal","what is the interest","the amount at the end","who pays"]'::jsonb, '["recall"]'::jsonb, ARRAY['G8_SIMPLE_INTEREST']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G8.MEASUR.MONEY.SIMPLE_INTEREST', 'MATH.G8.MEASUR.MONEY', 'mathematics', 8, 'Calculate simple interest and the amount', ARRAY['MATH.G8.MEASUR.MONEY.b']::text[], 'The child uses I = P × R × T / 100 with the time in years (months divided by 12), and adds the interest to the principal for the amount: 20,000 shillings at 8% for 3 years earns 4,800 shillings, an amount of 24,800 shillings.', '["simple interest for","the amount after","time in months","a loan"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G8_SIMPLE_INTEREST']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G8.MEASUR.MONEY.SIMPLE_INTEREST_WORK_BACK', 'MATH.G8.MEASUR.MONEY', 'mathematics', 8, 'Find the principal, rate or time from simple interest', ARRAY['MATH.G8.MEASUR.MONEY.b']::text[], 'The child rearranges I = PRT/100 (or uses the interest for one year) to find the missing quantity: interest of 3,000 shillings on 15,000 shillings over 2 years is 1,500 a year, which is 10% a year.', '["find the rate","how many years","how much was borrowed","interest for one year"]'::jsonb, '["procedure","reasoning"]'::jsonb, ARRAY['G8_SIMPLE_INTEREST']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G8.MEASUR.MONEY.COMPOUND_INTEREST', 'MATH.G8.MEASUR.MONEY', 'mathematics', 8, 'Calculate compound interest year by year up to three years', ARRAY['MATH.G8.MEASUR.MONEY.c']::text[], 'The child works out each year''s interest on the amount at the start of that year, adds it on, and repeats, then gives the amount or the interest as asked: 10,000 shillings at 10% compound becomes 11,000 then 12,100 after 2 years, interest 2,100; and explains why this beats simple interest at the same rate.', '["amount after 2 years","complete the table","compound interest earned","why does she end with more"]'::jsonb, '["procedure","reasoning"]'::jsonb, ARRAY['G9_COMPOUND_INTEREST', 'G8_SIMPLE_INTEREST']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G8.MEASUR.MONEY.DEPRECIATION', 'MATH.G8.MEASUR.MONEY', 'mathematics', 8, 'Work out depreciation year by year up to three years', ARRAY['MATH.G8.MEASUR.MONEY.d']::text[], 'The child takes the percentage off the value at the start of each year (not off the new price), so the fall gets smaller each year: a motorcycle of 120,000 shillings losing 20% a year is worth 96,000 then 76,800 after 2 years.', '["value after 2 years","complete the table","how much value is lost","why is the total not 40%"]'::jsonb, '["procedure","reasoning"]'::jsonb, ARRAY['G8_PROFIT_LOSS']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G8.MEASUR.MONEY.APPRECIATION', 'MATH.G8.MEASUR.MONEY', 'mathematics', 8, 'Work out appreciation year by year and say what appreciates', ARRAY['MATH.G8.MEASUR.MONEY.d']::text[], 'The child adds the percentage of the value at the start of each year, and sorts goods into ones that usually gain value (land, a plot in a growing town) and ones that lose it (phones, vehicles, furniture): land of 500,000 shillings appreciating 10% a year is worth 605,000 after 2 years.', '["value of land after","appreciate or depreciate","which is worth buying","complete the table"]'::jsonb, '["procedure","reasoning"]'::jsonb, ARRAY['G8_PROFIT_LOSS']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G8.MEASUR.MONEY.HIRE_PURCHASE', 'MATH.G8.MEASUR.MONEY', 'mathematics', 8, 'Work out hire purchase costs and compare plans', ARRAY['MATH.G8.MEASUR.MONEY.e']::text[], 'The child adds the deposit to all the instalments (number times each instalment) for the hire purchase price, subtracts the cash price for the extra paid, and compares plans by their totals: a deposit of 5,000 and 10 instalments of 2,000 cost 25,000 against a cash price of 21,000, so 4,000 more.', '["how much more than the cash price","which plan costs least","total hire purchase price","the balance after the deposit"]'::jsonb, '["procedure","modelling"]'::jsonb, ARRAY['G8_PROFIT_LOSS']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G8.GEOMET.GEOMETRICAL_CONSTRUCTION.CONSTRUCT_PARALLEL_PERPENDICULAR', 'MATH.G8.GEOMET.GEOMETRICAL_CONSTRUCTION', 'mathematics', 8, 'Construct parallel and perpendicular lines with ruler and compasses', ARRAY['MATH.G8.GEOMET.GEOMETRICAL_CONSTRUCTION.a']::text[], 'The child constructs a perpendicular from a point to a line and at a point on a line (arcs of the same radius, then joining the crossing), and a parallel line through a point (by copying an angle or by two perpendiculars), keeping the compass radius fixed where the method needs it.', '["steps to draw a perpendicular","a line through P parallel to AB","which step is first","why the arcs must be equal"]'::jsonb, '["procedure","reasoning"]'::jsonb, ARRAY['G9_CONSTRUCTION', 'G7_CONSTRUCTIONS']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G8.GEOMET.GEOMETRICAL_CONSTRUCTION.DIVIDE_LINE_METHOD', 'MATH.G8.GEOMET.GEOMETRICAL_CONSTRUCTION', 'mathematics', 8, 'Know the method for dividing a line proportionally and why it works', ARRAY['MATH.G8.GEOMET.GEOMETRICAL_CONSTRUCTION.b']::text[], 'The child draws a ray from one end, marks as many equal parts as the ratio numbers added (2 : 3 needs 5), joins the last mark to the other end, and draws parallel lines through the other marks, explaining that parallel lines cut the line in the same ratio as the ray.', '["how many equal parts","why must the lines be parallel","order of the steps","which mark is joined"]'::jsonb, '["procedure","reasoning"]'::jsonb, ARRAY['G9_CONSTRUCTION']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G8.GEOMET.GEOMETRICAL_CONSTRUCTION.DIVIDE_LINE_LENGTHS', 'MATH.G8.GEOMET.GEOMETRICAL_CONSTRUCTION', 'mathematics', 8, 'Find the lengths when a line is divided proportionally', ARRAY['MATH.G8.GEOMET.GEOMETRICAL_CONSTRUCTION.b']::text[], 'The child adds the ratio numbers, divides the length by the total to find one part, and gives each piece in order from the named end: a line of 15 cm divided in the ratio 2 : 3 from A gives 6 cm and 9 cm.', '["length of the part next to A","length of each equal part","a boundary shared between plots","how many parts"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G9_CONSTRUCTION']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G8.GEOMET.GEOMETRICAL_CONSTRUCTION.POLYGON_ANGLE_PROPERTIES', 'MATH.G8.GEOMET.GEOMETRICAL_CONSTRUCTION', 'mathematics', 8, 'Identify the angle properties of polygons', ARRAY['MATH.G8.GEOMET.GEOMETRICAL_CONSTRUCTION.c']::text[], 'The child finds the angle sum as (n - 2) × 180° (or (2n - 4) right angles), the exterior angle of a regular polygon as 360° ÷ n and the interior angle as 180° minus that, and knows the exterior angles always add to 360°: a regular pentagon has interior angles of 108°.', '["interior angle of a regular polygon","sum of the angles","right angles and sides","exterior angle"]'::jsonb, '["procedure","recall"]'::jsonb, ARRAY['G8_POLYGON_ANGLES', 'G9_CONSTRUCTION']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G8.GEOMET.GEOMETRICAL_CONSTRUCTION.CONSTRUCT_REGULAR_POLYGON', 'MATH.G8.GEOMET.GEOMETRICAL_CONSTRUCTION', 'mathematics', 8, 'Plan the construction of regular polygons up to a hexagon', ARRAY['MATH.G8.GEOMET.GEOMETRICAL_CONSTRUCTION.d']::text[], 'The child uses equal sides and the interior angle at each corner (108° for a pentagon, 120° for a hexagon), or equal angles at the centre (360° ÷ n), and knows a regular hexagon''s side equals the radius of its circle, so it can be stepped round with compasses.', '["angle at each corner","angle at the centre","a hexagon with compasses","is this polygon regular"]'::jsonb, '["procedure","reasoning"]'::jsonb, ARRAY['G9_CONSTRUCTION', 'G8_POLYGON_ANGLES']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G8.GEOMET.GEOMETRICAL_CONSTRUCTION.CONSTRUCT_IRREGULAR_POLYGON', 'MATH.G8.GEOMET.GEOMETRICAL_CONSTRUCTION', 'mathematics', 8, 'Plan the construction of irregular polygons up to a hexagon from given sides and angles', ARRAY['MATH.G8.GEOMET.GEOMETRICAL_CONSTRUCTION.e']::text[], 'The child sketches and labels the polygon first, draws one side, constructs or measures each angle at the right corner, marks each side length in order, and checks the last side closes the shape.', '["order of construction","which angle is at B","sketch first","does the shape close"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G9_CONSTRUCTION']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G8.GEOMET.GEOMETRICAL_CONSTRUCTION.CIRCUMCIRCLE', 'MATH.G8.GEOMET.GEOMETRICAL_CONSTRUCTION', 'mathematics', 8, 'Construct the circle passing through the vertices of a triangle', ARRAY['MATH.G8.GEOMET.GEOMETRICAL_CONSTRUCTION.f']::text[], 'The child bisects two sides at right angles, takes the meeting point as the centre and the distance to a corner as the radius, explains that every point on a perpendicular bisector is the same distance from both ends of the side, and knows that for a right-angled triangle the centre is the midpoint of the longest side.', '["radius of the circle through the corners","which construction finds the centre","why does it work","right-angled triangle"]'::jsonb, '["procedure","reasoning"]'::jsonb, ARRAY['G9_CONSTRUCTION']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G8.GEOMET.GEOMETRICAL_CONSTRUCTION.INCIRCLE', 'MATH.G8.GEOMET.GEOMETRICAL_CONSTRUCTION', 'mathematics', 8, 'Construct the circle touching the sides of a triangle', ARRAY['MATH.G8.GEOMET.GEOMETRICAL_CONSTRUCTION.g']::text[], 'The child bisects two angles, takes the meeting point as the centre, draws a perpendicular from it to one side to get the radius, and explains that every point on an angle bisector is the same distance from the two sides of the angle.', '["which construction finds the centre","how to find the radius","why bisect the angles","the biggest circle that fits"]'::jsonb, '["procedure","reasoning"]'::jsonb, ARRAY['G9_CONSTRUCTION']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G8.GEOMET.COORDINATES_AND_GRAPHS.CARTESIAN_PLANE', 'MATH.G8.GEOMET.COORDINATES_AND_GRAPHS', 'mathematics', 8, 'Draw and label a Cartesian plane', ARRAY['MATH.G8.GEOMET.COORDINATES_AND_GRAPHS.a']::text[], 'The child draws the x-axis across and the y-axis up, crossing at the origin (0, 0), numbers both with equal steps including negative numbers to the left and below, and labels the axes x and y.', '["label the axes","where is the origin","which quadrant","equal steps"]'::jsonb, '["representation"]'::jsonb, ARRAY['G8_COORDINATES']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G8.GEOMET.COORDINATES_AND_GRAPHS.READ_COORDINATES', 'MATH.G8.GEOMET.COORDINATES_AND_GRAPHS', 'mathematics', 8, 'Identify the coordinates of points on the Cartesian plane', ARRAY['MATH.G8.GEOMET.COORDINATES_AND_GRAPHS.b']::text[], 'The child reads a point as (across, up) from the origin, finds a point from another by moving across then up, gives the missing corner of a shape from its sides, and reads the height of a point on a graph at a given value across.', '["coordinates of the point","the fourth corner","read the fare at","which point shows the shop"]'::jsonb, '["representation"]'::jsonb, ARRAY['G8_COORDINATES', 'G8_LINEAR_GRAPHS']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G8.GEOMET.COORDINATES_AND_GRAPHS.PLOT_POINTS', 'MATH.G8.GEOMET.COORDINATES_AND_GRAPHS', 'mathematics', 8, 'Plot points on the Cartesian plane, in all four quadrants', ARRAY['MATH.G8.GEOMET.COORDINATES_AND_GRAPHS.c']::text[], 'The child starts at the origin, moves along the x-axis first (right for positive, left for negative) and then parallel to the y-axis (up for positive, down for negative), and marks the point where the grid lines cross.', '["plot the point","how do you reach","start at the origin and move","which point is"]'::jsonb, '["representation"]'::jsonb, ARRAY['G8_COORDINATES']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G8.GEOMET.COORDINATES_AND_GRAPHS.TABLE_OF_VALUES', 'MATH.G8.GEOMET.COORDINATES_AND_GRAPHS', 'mathematics', 8, 'Generate a table of values for a linear equation', ARRAY['MATH.G8.GEOMET.COORDINATES_AND_GRAPHS.d']::text[], 'The child substitutes each x, negative ones included, into y = mx + c, multiplying before adding, and checks that the y values go up (or down) by the same step: y = 2x - 3 gives -7, -5, -3, -1, 1 for x = -2 to 2.', '["complete the table","which step has the mistake","use the pattern","y when x is"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G8_LINEAR_GRAPHS']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G8.GEOMET.COORDINATES_AND_GRAPHS.CHOOSE_SCALE', 'MATH.G8.GEOMET.COORDINATES_AND_GRAPHS', 'mathematics', 8, 'Determine an appropriate scale for a graph', ARRAY['MATH.G8.GEOMET.COORDINATES_AND_GRAPHS.e']::text[], 'The child divides the largest value by the number of squares (or centimetres) on the axis and picks the smallest convenient scale that fits (1, 2, 5, 10 or 20 units a square), so the graph uses most of the paper.', '["what scale","why is this scale not suitable","the smallest scale that fits","units for each centimetre"]'::jsonb, '["reasoning"]'::jsonb, ARRAY['G8_LINEAR_GRAPHS']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G8.GEOMET.COORDINATES_AND_GRAPHS.DRAW_LINEAR_GRAPH', 'MATH.G8.GEOMET.COORDINATES_AND_GRAPHS', 'mathematics', 8, 'Draw a linear graph from a table of values', ARRAY['MATH.G8.GEOMET.COORDINATES_AND_GRAPHS.f']::text[], 'The child plots every point from the table, checks they lie in a straight line (a point off the line means a mistake in the table), and draws one straight line with a ruler through them across the whole range.', '["draw the line","which point is wrong","is it a straight line","extend the line"]'::jsonb, '["representation"]'::jsonb, ARRAY['G8_LINEAR_GRAPHS']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G8.GEOMET.COORDINATES_AND_GRAPHS.SOLVE_GRAPHICALLY', 'MATH.G8.GEOMET.COORDINATES_AND_GRAPHS', 'mathematics', 8, 'Solve simultaneous linear equations graphically', ARRAY['MATH.G8.GEOMET.COORDINATES_AND_GRAPHS.g']::text[], 'The child draws both lines on one set of axes, reads the crossing point as (x, y), gives both values as the solution, explains that the crossing is the only point on both lines, and checks it in both equations.', '["where do the lines meet","for how many hours is the cost the same","why is the crossing the solution","read the solution"]'::jsonb, '["representation","reasoning"]'::jsonb, ARRAY['G8_LINEAR_GRAPHS']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G8.GEOMET.COORDINATES_AND_GRAPHS.SIMULTANEOUS_GRAPH_CONTEXT', 'MATH.G8.GEOMET.COORDINATES_AND_GRAPHS', 'mathematics', 8, 'Apply simultaneous equations and their graphs in real life', ARRAY['MATH.G8.GEOMET.COORDINATES_AND_GRAPHS.h']::text[], 'The child forms a cost line for each choice (a fixed charge plus a rate), finds where they meet (by the graph or by setting the costs equal), and says which choice is cheaper before and after that point: 200 + 30d and 100 + 50d meet at d = 5 km.', '["where the costs are equal","which company is cheaper","the distance where the lines meet","compare two plans"]'::jsonb, '["modelling"]'::jsonb, ARRAY['G8_LINEAR_GRAPHS']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G8.GEOMET.SCALE_DRAWING.REPRESENT_TO_SCALE', 'MATH.G8.GEOMET.SCALE_DRAWING', 'mathematics', 8, 'Represent lengths to a given scale', ARRAY['MATH.G8.GEOMET.SCALE_DRAWING.a']::text[], 'The child divides each real length by what 1 cm stands for to get the length to draw, keeps each drawn length matched to its own real length, and checks the drawn lengths are shorter than the real ones: with 1 cm to 5 m, 20 m, 35 m and 12.5 m are drawn as 4 cm, 7 cm and 2.5 cm.', '["lengths to draw","which list fits the scale","draw to scale","match each length"]'::jsonb, '["representation"]'::jsonb, ARRAY['G8_SCALE_DRAWING']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G8.GEOMET.SCALE_DRAWING.ACTUAL_TO_SCALE', 'MATH.G8.GEOMET.SCALE_DRAWING', 'mathematics', 8, 'Convert an actual length to a scale length', ARRAY['MATH.G8.GEOMET.SCALE_DRAWING.b']::text[], 'The child divides the real length by what 1 cm stands for (changing units first if needed) to find the length on the plan: a wall of 24 m with 1 cm to 4 m is 6 cm on the plan.', '["how long on the map","length to draw","real to plan","in cm"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G8_SCALE_DRAWING']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G8.GEOMET.SCALE_DRAWING.SCALE_TO_ACTUAL', 'MATH.G8.GEOMET.SCALE_DRAWING', 'mathematics', 8, 'Convert a scale length to an actual length', ARRAY['MATH.G8.GEOMET.SCALE_DRAWING.c']::text[], 'The child multiplies the length on the plan or map by what 1 cm stands for, keeps the unit the scale gives, and finds real differences by subtracting real lengths (or scaling the difference): 7.5 cm on a plan of 1 cm to 2 m is 15 m.', '["real length","how much longer in real life","how far apart","from the plan"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G8_SCALE_DRAWING']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G8.GEOMET.SCALE_DRAWING.STATEMENT_SCALE', 'MATH.G8.GEOMET.SCALE_DRAWING', 'mathematics', 8, 'Interpret and write a linear scale in statement form', ARRAY['MATH.G8.GEOMET.SCALE_DRAWING.d', 'MATH.G8.GEOMET.SCALE_DRAWING.e']::text[], 'The child reads "1 cm represents 5 km" as each centimetre on the map standing for 5 km on the ground, and writes a statement from a map and real distance by dividing the real distance by the map distance: 6 cm for 30 km gives "1 cm represents 5 km".', '["what does 1 cm stand for","write the scale as a statement","which sentence gives the scale","interpret the scale"]'::jsonb, '["representation"]'::jsonb, ARRAY['G8_SCALE_FORMS']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G8.GEOMET.SCALE_DRAWING.RATIO_SCALE', 'MATH.G8.GEOMET.SCALE_DRAWING', 'mathematics', 8, 'Interpret and write a linear scale in ratio form', ARRAY['MATH.G8.GEOMET.SCALE_DRAWING.f', 'MATH.G8.GEOMET.SCALE_DRAWING.g']::text[], 'The child reads 1 : 500,000 as 1 cm standing for 500,000 cm (5 km), writes a ratio scale with both lengths in cm and the drawing as 1, and knows a smaller second number shows more detail: a 2 cm line for 50 m is 1 : 2,500.', '["what does 1 cm stand for in km","write the scale as a ratio","which map shows more detail","find n"]'::jsonb, '["representation","reasoning"]'::jsonb, ARRAY['G8_SCALE_FORMS']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G8.GEOMET.SCALE_DRAWING.CONVERT_SCALE_FORMS', 'MATH.G8.GEOMET.SCALE_DRAWING', 'mathematics', 8, 'Convert a scale between statement form and ratio form', ARRAY['MATH.G8.GEOMET.SCALE_DRAWING.h']::text[], 'The child changes the real length in a statement to centimetres to write the ratio ("1 cm represents 2 km" is 1 : 200,000), and divides the ratio number by 100 for metres or by 100,000 for kilometres to write the statement.', '["statement to ratio","ratio to statement","which step has the mistake","each centimetre stands for"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G8_SCALE_FORMS']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G8.GEOMET.SCALE_DRAWING.MAKE_SCALE_DRAWING', 'MATH.G8.GEOMET.SCALE_DRAWING', 'mathematics', 8, 'Make a scale drawing', ARRAY['MATH.G8.GEOMET.SCALE_DRAWING.i']::text[], 'The child chooses a scale that fits the paper, works out every length to draw, draws the shape with a ruler (and protractor or compasses for angles), writes the scale on the drawing, and checks one length back.', '["choose a scale","lengths to draw","what goes on the drawing","check a length"]'::jsonb, '["representation","procedure"]'::jsonb, ARRAY['G8_SCALE_DRAWING']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G8.GEOMET.SCALE_DRAWING.SCALE_IN_CONTEXT', 'MATH.G8.GEOMET.SCALE_DRAWING', 'mathematics', 8, 'Apply scale drawing to maps, routes and plans', ARRAY['MATH.G8.GEOMET.SCALE_DRAWING.j']::text[], 'The child finds the scale from a map and a real distance, adds the legs of a journey before or after scaling, changes cm to km by dividing by 100,000, and scales both lengths of a plot before finding its area: a plan 5 cm by 3 cm at 1 cm to 20 m is a plot of 100 m by 60 m, 6,000 m².', '["length of the whole journey","find the scale of the map","real area of the shamba","distance between towns"]'::jsonb, '["modelling"]'::jsonb, ARRAY['G8_SCALE_DRAWING']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G8.GEOMET.COMMON_SOLIDS.IDENTIFY_SOLIDS', 'MATH.G8.GEOMET.COMMON_SOLIDS', 'mathematics', 8, 'Identify common solids and count their faces, edges and vertices', ARRAY['MATH.G8.GEOMET.COMMON_SOLIDS.a']::text[], 'The child names cubes, cuboids, cylinders, pyramids and cones from objects around them, counts their faces, edges and vertices, and uses faces + vertices - edges = 2 to find a missing count: a cube has 6 faces, 8 vertices and 12 edges.', '["name the solid","how many edges","faces, vertices and edges","which objects are cylinders"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY['G8_VOLUME_ADV']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G8.GEOMET.COMMON_SOLIDS.SKETCH_NETS', 'MATH.G8.GEOMET.COMMON_SOLIDS', 'mathematics', 8, 'Sketch the nets of cubes, cuboids, cylinders, pyramids and cones', ARRAY['MATH.G8.GEOMET.COMMON_SOLIDS.b']::text[], 'The child sketches a net with each face the right shape and size, edges that will meet the same length (the rectangle of a cylinder is as long as the circumference), and decides whether a net folds into the solid: four squares in a row with one square above and one below makes a cube.', '["does this net fold into a cube","length of the rectangle in a cylinder net","sketch the net","which faces meet"]'::jsonb, '["representation","reasoning"]'::jsonb, ARRAY['G8_VOLUME_ADV', 'G8_SURFACE_AREA']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G8.GEOMET.COMMON_SOLIDS.SA_FROM_NET', 'MATH.G8.GEOMET.COMMON_SOLIDS', 'mathematics', 8, 'Work out the surface area of a solid from its net', ARRAY['MATH.G8.GEOMET.COMMON_SOLIDS.c']::text[], 'The child finds the area of each shape in the net and adds them (two circles and a rectangle for a closed cylinder), finds a radius from the rectangle''s length when needed, and knows that when edges are k times as long the surface area is k² times and the volume k³ times as big.', '["surface area from the net","find the radius from the rectangle","a bigger cube","what happens to the area and the volume"]'::jsonb, '["procedure","reasoning"]'::jsonb, ARRAY['G8_SURFACE_AREA']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G8.GEOMET.COMMON_SOLIDS.FOLD_NET_MEASURES', 'MATH.G8.GEOMET.COMMON_SOLIDS', 'mathematics', 8, 'Find the measures of a solid folded from a net', ARRAY['MATH.G8.GEOMET.COMMON_SOLIDS.c']::text[], 'The child works out the length, width and height of the solid a flat sheet folds into (cutting a square of side x from each corner takes 2x off each side and leaves a height of x), and uses them for its volume: a 30 cm by 20 cm sheet with 5 cm squares cut gives a tray of 20 × 10 × 5 = 1,000 cm³.', '["volume of the tray","size of the base","height after folding","which sheet gives the bigger box"]'::jsonb, '["modelling"]'::jsonb, ARRAY['G8_VOLUME_ADV']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G8.GEOMET.COMMON_SOLIDS.SURFACE_DISTANCE', 'MATH.G8.GEOMET.COMMON_SOLIDS', 'mathematics', 8, 'Find the shortest distance between two points on the surface of a solid', ARRAY['MATH.G8.GEOMET.COMMON_SOLIDS.d']::text[], 'The child unfolds the faces the path crosses into one flat shape, joins the two points with a straight line, and finds its length with Pythagoras (two faces of a box) or as a fraction of the circumference (round a tin): from one side of a tin of radius 7 cm to the opposite point is 22 cm along the rim.', '["shortest distance for the ant","the beetle on the tin","unfold the faces","stay on the surface"]'::jsonb, '["reasoning","modelling"]'::jsonb, ARRAY['G8_VOLUME_ADV', 'G7_PYTHAGORAS']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G8.GEOMET.COMMON_SOLIDS.HOLLOW_COMPACT_MODELS', 'MATH.G8.GEOMET.COMMON_SOLIDS', 'mathematics', 8, 'Plan models of hollow and compact solids', ARRAY['MATH.G8.GEOMET.COMMON_SOLIDS.e']::text[], 'The child tells a hollow solid (a container, a tin, a box) from a compact one (a brick, a log), and plans a hollow model from a net with flaps for gluing, faces of matching sizes, and the right faces left open or closed.', '["hollow or compact","where do the flaps go","will the edges meet","an open box net"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G8_VOLUME_ADV']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
