INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.SQUARES_AND_SQUARE_ROOTS.SQUARE_FROM_TABLE.M_TABLE_VALUE_NOT_SCALED', 'MATH.G8.NUMBER.SQUARES_AND_SQUARE_ROOTS.SQUARE_FROM_TABLE', 'Gives the table value for 4.36 as the square of 43.6.', '{"question":"43.6² using 4.36² = 19.01","wrong_answer":"19.01","correct_answer":"1,901"}'::jsonb, 'Reads the table and forgets the number was ten times bigger.', 'The answer 19.01 as a wrong option, with a reason that names the idea.', 'Write 43.6 = 4.36 × 10, so the square is 19.01 × 100.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.SQUARES_AND_SQUARE_ROOTS.SQUARE_FROM_TABLE.M_SCALE_NOT_SQUARED', 'MATH.G8.NUMBER.SQUARES_AND_SQUARE_ROOTS.SQUARE_FROM_TABLE', 'Multiplies the table value by 10 when the number was 10 times bigger.', '{"question":"43.6² using 4.36² = 19.01","wrong_answer":"190.1","correct_answer":"1,901"}'::jsonb, 'Thinks the square grows as much as the number.', 'The answer 190.1 as a wrong option, with a reason that names the idea.', '10 times bigger each side makes 10 × 10 = 100 times the square.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.SQUARES_AND_SQUARE_ROOTS.SQUARE_FROM_TABLE.M_POINT_ONE_PLACE_OUT', 'MATH.G8.NUMBER.SQUARES_AND_SQUARE_ROOTS.SQUARE_FROM_TABLE', 'Moves the decimal point one place too far.', '{"question":"43.6² using 4.36² = 19.01","wrong_answer":"19,010","correct_answer":"1,901"}'::jsonb, 'Counts the places wrongly.', 'The answer 19,010 as a wrong option, with a reason that names the idea.', 'Times 100 moves the point two places only.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.SQUARES_AND_SQUARE_ROOTS.SQUARE_FROM_TABLE.M_SQUARE_AS_DOUBLE', 'MATH.G8.NUMBER.SQUARES_AND_SQUARE_ROOTS.SQUARE_FROM_TABLE', 'Doubles the number instead of squaring it.', '{"question":"43.6²","wrong_answer":"87.2","correct_answer":"1,901"}'::jsonb, 'Reads the small 2 as "times 2".', 'The answer 87.2 as a wrong option, with a reason that names the idea.', 'The small 2 means the number times itself.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.SQUARES_AND_SQUARE_ROOTS.SQUARE_FROM_TABLE.M_TABLE_CELL_MISREAD', 'MATH.G8.NUMBER.SQUARES_AND_SQUARE_ROOTS.SQUARE_FROM_TABLE', 'Reads the next row or column of the table.', '{"question":"From the table, 4.36²","wrong_answer":"19.10 (the value for 4.37)","correct_answer":"19.01"}'::jsonb, 'Loses the place on a crowded table.', 'The answer 19.10 (the value for 4.37) as a wrong option, with a reason that names the idea.', 'Row 4.3, then across to the column headed 6.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.SQUARES_AND_SQUARE_ROOTS.SQUARE_AREA_COST.M_PERIMETER_FOR_AREA', 'MATH.G8.NUMBER.SQUARES_AND_SQUARE_ROOTS.SQUARE_AREA_COST', 'Uses the distance round the square instead of its area.', '{"question":"A square room of side 4.5 m; tiles 800 shillings a m². Cost?","wrong_answer":"14,400","correct_answer":"16,200"}'::jsonb, 'Confuses the edge with the floor.', 'The answer 14,400 as a wrong option, with a reason that names the idea.', 'Tiles cover the floor: area = side × side.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.SQUARES_AND_SQUARE_ROOTS.SQUARE_AREA_COST.M_AREA_AS_TWO_SIDES', 'MATH.G8.NUMBER.SQUARES_AND_SQUARE_ROOTS.SQUARE_AREA_COST', 'Takes the area of a square as the side times 2.', '{"question":"A square room of side 4.5 m; tiles 800 a m². Cost?","wrong_answer":"7,200","correct_answer":"16,200"}'::jsonb, 'Reads "squared" as "doubled".', 'The answer 7,200 as a wrong option, with a reason that names the idea.', 'Area = 4.5 × 4.5, not 4.5 × 2.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.SQUARES_AND_SQUARE_ROOTS.SQUARE_AREA_COST.M_ONE_SIDE_ONLY', 'MATH.G8.NUMBER.SQUARES_AND_SQUARE_ROOTS.SQUARE_AREA_COST', 'Multiplies the price by one side only.', '{"question":"A square room of side 4.5 m; tiles 800 a m². Cost?","wrong_answer":"3,600","correct_answer":"16,200"}'::jsonb, 'Prices a strip 1 m wide.', 'The answer 3,600 as a wrong option, with a reason that names the idea.', 'The floor is the side times the side.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.SQUARES_AND_SQUARE_ROOTS.SQUARE_AREA_COST.M_AREA_UNIT_MIXED', 'MATH.G8.NUMBER.SQUARES_AND_SQUARE_ROOTS.SQUARE_AREA_COST', 'Squares a side in centimetres and prices it per square metre.', '{"question":"A square tile of side 30 cm; cost 1,000 shillings a m². Cost of one tile?","wrong_answer":"900,000","correct_answer":"90"}'::jsonb, 'Does not change cm to m before squaring.', 'The answer 900,000 as a wrong option, with a reason that names the idea.', '30 cm = 0.3 m; 0.3² = 0.09 m².', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.SQUARES_AND_SQUARE_ROOTS.ROOT_FROM_TABLE.M_ROOT_TABLE_NOT_SCALED', 'MATH.G8.NUMBER.SQUARES_AND_SQUARE_ROOTS.ROOT_FROM_TABLE', 'Gives the table root of the smaller number for the bigger one.', '{"question":"√4,500 using √45 = 6.708","wrong_answer":"6.708","correct_answer":"67.08"}'::jsonb, 'Forgets the number was 100 times bigger.', 'The answer 6.708 as a wrong option, with a reason that names the idea.', '4,500 = 45 × 100, so √4,500 = 6.708 × 10.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.SQUARES_AND_SQUARE_ROOTS.ROOT_FROM_TABLE.M_ROOT_SCALED_LIKE_NUMBER', 'MATH.G8.NUMBER.SQUARES_AND_SQUARE_ROOTS.ROOT_FROM_TABLE', 'Multiplies the root by 100 when the number was 100 times bigger.', '{"question":"√4,500 using √45 = 6.708","wrong_answer":"670.8","correct_answer":"67.08"}'::jsonb, 'Thinks the root grows as much as the number.', 'The answer 670.8 as a wrong option, with a reason that names the idea.', 'A number 100 times bigger has a root 10 times bigger.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
