INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_.FRACTION_AS_RATIO.M_FRACTION_AS_PART_PART', 'MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_.FRACTION_AS_RATIO', 'Writes a fraction of the whole as the part-to-part ratio directly.', '{"question":"2/5 of a class are girls. Girls : boys?","wrong_answer":"2 : 5","correct_answer":"2 : 3"}'::jsonb, 'Uses the denominator as the other part.', 'The answer 2 : 5 as a wrong option, with a reason that names the idea.', 'The other part is 5 - 2 = 3.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_.FRACTION_AS_RATIO.M_RATIO_ORDER_SWAPPED', 'MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_.FRACTION_AS_RATIO', 'Writes the ratio in the opposite order to the question.', '{"question":"15 boys and 12 girls. Boys : girls?","wrong_answer":"4 : 5","correct_answer":"5 : 4"}'::jsonb, 'Writes the smaller number first.', 'The answer 4 : 5 as a wrong option, with a reason that names the idea.', 'Follow the order in the question.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
