INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_.RATIO_INCREASE_DECREASE.M_RATIO_FLIPPED', 'MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_.RATIO_INCREASE_DECREASE', 'Multiplies by the ratio the wrong way up, so an increase becomes a decrease.', '{"question":"Increase 600 g in the ratio 5 : 3","wrong_answer":"360 g","correct_answer":"1,000 g"}'::jsonb, 'Does not check which number is new.', 'The answer 360 g as a wrong option, with a reason that names the idea.', 'New : old = 5 : 3, so multiply by 5/3: more.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_.RATIO_INCREASE_DECREASE.M_RATIO_ADDED', 'MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_.RATIO_INCREASE_DECREASE', 'Adds or takes away a ratio number from the quantity.', '{"question":"Increase 600 g in the ratio 5 : 3","wrong_answer":"605 g","correct_answer":"1,000 g"}'::jsonb, 'Treats the ratio like an amount.', 'The answer 605 g as a wrong option, with a reason that names the idea.', 'A ratio says how many times, not how many more.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_.RATIO_INCREASE_DECREASE.M_NOT_DIVIDED_BY_OLD', 'MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_.RATIO_INCREASE_DECREASE', 'Multiplies by the new number without dividing by the old.', '{"question":"Increase 600 g in the ratio 5 : 3","wrong_answer":"3,000 g","correct_answer":"1,000 g"}'::jsonb, 'Leaves out finding one part.', 'The answer 3,000 g as a wrong option, with a reason that names the idea.', 'Divide by 3 first: 200 g a part.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_.RATIO_INCREASE_DECREASE.M_ONE_PART_ONLY', 'MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_.RATIO_INCREASE_DECREASE', 'Gives the value of one part as the new amount.', '{"question":"Decrease a rent of 12,000 in the ratio 3 : 4","wrong_answer":"3,000","correct_answer":"9,000"}'::jsonb, 'Stops after dividing.', 'The answer 3,000 as a wrong option, with a reason that names the idea.', 'The new rent is 3 parts.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_.RATIO_INCREASE_DECREASE.M_ONE_PART_MULTIPLIED', 'MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_.RATIO_INCREASE_DECREASE', 'Multiplies by the old number to find one part.', '{"question":"A fare of 80 increased 5 : 4. One part?","wrong_answer":"320","correct_answer":"20"}'::jsonb, 'Picks the wrong operation for one part.', 'The answer 320 as a wrong option, with a reason that names the idea.', 'One part = old ÷ its parts: 80 ÷ 4.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_.RATIO_INCREASE_DECREASE.M_DIVIDED_TWICE', 'MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_.RATIO_INCREASE_DECREASE', 'Divides by both ratio numbers.', '{"question":"Increase 600 in the ratio 5 : 3","wrong_answer":"40","correct_answer":"1,000"}'::jsonb, 'Uses both numbers the same way.', 'The answer 40 as a wrong option, with a reason that names the idea.', 'Divide by the old, multiply by the new.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_.PERCENT_CHANGE.M_CHANGE_NOT_PERCENT', 'MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_.PERCENT_CHANGE', 'Gives the change in shillings, not as a percentage.', '{"question":"A fare goes from 80 to 100 shillings. Percentage increase?","wrong_answer":"20","correct_answer":"25%"}'::jsonb, 'Stops at the difference.', 'The answer 20 as a wrong option, with a reason that names the idea.', 'Compare the change with the old fare out of 100.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_.PERCENT_CHANGE.M_PCT_OF_NEW', 'MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_.PERCENT_CHANGE', 'Divides the change by the new amount.', '{"question":"A fare goes from 80 to 100. Percentage increase?","wrong_answer":"20%","correct_answer":"25%"}'::jsonb, 'Uses the last number met.', 'The answer 20% as a wrong option, with a reason that names the idea.', 'Percentage change is against the original.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_.PERCENT_CHANGE.M_NEW_AS_PERCENT', 'MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_.PERCENT_CHANGE', 'Gives the new amount as a percentage of the old as the change.', '{"question":"80 to 100. Percentage increase?","wrong_answer":"125%","correct_answer":"25%"}'::jsonb, 'Forgets to take away 100%.', 'The answer 125% as a wrong option, with a reason that names the idea.', '125% of the old means 25% more.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_.PERCENT_CHANGE.M_DECIMAL_NOT_PERCENT', 'MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_.PERCENT_CHANGE', 'Leaves the change as a decimal.', '{"question":"80 to 100. Percentage increase?","wrong_answer":"0.25","correct_answer":"25%"}'::jsonb, 'Does not multiply by 100.', 'The answer 0.25 as a wrong option, with a reason that names the idea.', 'Times 100 for a percentage.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_.PERCENT_CHANGE.M_BIGGEST_RISE_FOR_PCT', 'MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_.PERCENT_CHANGE', 'Picks the biggest rise in number as the biggest percentage rise.', '{"question":"School A grew from 100 to 140 learners, school B from 400 to 460. Which had the greater percentage increase?","wrong_answer":"B, it gained 60","correct_answer":"A (40% against 15%)"}'::jsonb, 'Compares the rises, not the rises against the start.', 'The answer B, it gained 60 as a wrong option, with a reason that names the idea.', 'Divide each rise by the number at its start.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_.PERCENT_CHANGE_REVERSE.M_REVERSE_PCT_OF_NEW', 'MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_.PERCENT_CHANGE_REVERSE', 'Takes the percentage of the new price and subtracts or adds it.', '{"question":"After a 20% rise a price is 960. Price before?","wrong_answer":"768","correct_answer":"800"}'::jsonb, 'Treats the new price as the original.', 'The answer 768 as a wrong option, with a reason that names the idea.', '960 is 120% of the old price: 1% is 8.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_.PERCENT_CHANGE_REVERSE.M_PCT_AS_SHILLINGS', 'MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_.PERCENT_CHANGE_REVERSE', 'Treats the percentage as a number of shillings.', '{"question":"After a 20% rise a price is 960. Price before?","wrong_answer":"940","correct_answer":"800"}'::jsonb, 'Reads 20% as 20 shillings.', 'The answer 940 as a wrong option, with a reason that names the idea.', '20% is a share of the price, not 20 shillings.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_.PERCENT_CHANGE_REVERSE.M_CHANGE_FOR_ORIGINAL', 'MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_.PERCENT_CHANGE_REVERSE', 'Gives the amount of the change as the original price.', '{"question":"After a 20% rise a price is 960. Price before?","wrong_answer":"160","correct_answer":"800"}'::jsonb, 'Stops at the change.', 'The answer 160 as a wrong option, with a reason that names the idea.', 'The question asks for the whole price before.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_.PERCENT_CHANGE_REVERSE.M_PCT_DIVIDED_BY_PCT', 'MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_.PERCENT_CHANGE_REVERSE', 'Divides the new price by the percentage change.', '{"question":"After a 20% rise a price is 960. Price before?","wrong_answer":"48","correct_answer":"800"}'::jsonb, 'Divides by the only other number.', 'The answer 48 as a wrong option, with a reason that names the idea.', 'Divide by 120 to find 1%, then times 100.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_.PROPORTION_IDENTIFY.M_DIRECT_AS_INVERSE', 'MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_.PROPORTION_IDENTIFY', 'Calls a direct proportion inverse, or the other way round.', '{"question":"Kilograms of sugar and the cost: direct or inverse?","wrong_answer":"inverse","correct_answer":"direct"}'::jsonb, 'Does not test what happens when one doubles.', 'The answer inverse as a wrong option, with a reason that names the idea.', 'Double the sugar: the cost doubles, so direct.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_.PROPORTION_IDENTIFY.M_ANY_LINK_AS_PROPORTION', 'MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_.PROPORTION_IDENTIFY', 'Calls two quantities in proportion just because both grow.', '{"question":"The age of a child and the height of the child","wrong_answer":"direct proportion","correct_answer":"neither"}'::jsonb, 'Thinks "both go up" is enough.', 'The answer direct proportion as a wrong option, with a reason that names the idea.', 'Proportion needs a fixed rule: double one, double the other.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_.PROPORTION_IDENTIFY.M_DECREASE_AS_INVERSE', 'MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_.PROPORTION_IDENTIFY', 'Calls it inverse when one quantity goes down, whatever the rule.', '{"question":"Litres of petrol used and litres left in a 50 litre tank","wrong_answer":"inverse proportion","correct_answer":"neither"}'::jsonb, 'Thinks "one up, one down" means inverse.', 'The answer inverse proportion as a wrong option, with a reason that names the idea.', 'Inverse means the product stays the same: double one, halve the other.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_.PROPORTION_IDENTIFY.M_UNLINKED_AS_PROPORTION', 'MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_.PROPORTION_IDENTIFY', 'Gives a proportion for two quantities that are not linked at all.', '{"question":"Learners in a class and the height of the classroom","wrong_answer":"direct","correct_answer":"neither"}'::jsonb, 'Assumes every pair in a question is linked.', 'The answer direct as a wrong option, with a reason that names the idea.', 'Ask: does changing one change the other at all?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_.PROPORTION_SOLVE.M_INVERSE_AS_DIRECT', 'MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_.PROPORTION_SOLVE', 'Uses direct proportion for an inverse situation.', '{"question":"6 workers take 10 days. 4 workers take?","wrong_answer":"6.7 days","correct_answer":"15 days"}'::jsonb, 'Multiplies by the ratio of workers.', 'The answer 6.7 days as a wrong option, with a reason that names the idea.', 'Fewer workers take more days: total work 60 worker-days.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_.PROPORTION_SOLVE.M_TOTAL_WORK_GIVEN', 'MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_.PROPORTION_SOLVE', 'Gives the total worker-days as the answer.', '{"question":"6 workers take 10 days. 4 workers take?","wrong_answer":"60","correct_answer":"15 days"}'::jsonb, 'Stops after finding the total work.', 'The answer 60 as a wrong option, with a reason that names the idea.', 'Share the 60 worker-days among 4 workers.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_.PROPORTION_SOLVE.M_PROPORTION_ADDED', 'MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_.PROPORTION_SOLVE', 'Adds or subtracts the change in workers to the days.', '{"question":"6 workers take 10 days. 4 workers take?","wrong_answer":"8","correct_answer":"15 days"}'::jsonb, 'Links the numbers by adding.', 'The answer 8 as a wrong option, with a reason that names the idea.', 'Workers and days multiply to a fixed total.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_.PROPORTION_SOLVE.M_PRODUCT_ROW_CHECK_MISSED', 'MATH.G8.NUMBER.RATES_RATIO_PROPORTIONS_.PROPORTION_SOLVE', 'Checks a table of inverse proportion by differences instead of products.', '{"question":"Workers 2, 4, 5, 8; days 20, 10, 9, 5. Which row is wrong?","wrong_answer":"8 workers","correct_answer":"5 workers (5 × 9 = 45, not 40)"}'::jsonb, 'Looks for a steady difference.', 'The answer 8 workers as a wrong option, with a reason that names the idea.', 'In inverse proportion, workers × days is the same in every row.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.FACTORISE_HCF.M_COMMON_FACTOR_NOT_HIGHEST', 'MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.FACTORISE_HCF', 'Takes out a common factor that is not the highest.', '{"question":"Factorise 12x + 18 fully","wrong_answer":"3(4x + 6)","correct_answer":"6(2x + 3)"}'::jsonb, 'Stops at the first common factor found.', 'The answer 3(4x + 6) as a wrong option, with a reason that names the idea.', 'Check the bracket: 4x + 6 still has a factor 2.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.FACTORISE_HCF.M_INSIDE_COEFFICIENT_GIVEN', 'MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.FACTORISE_HCF', 'Gives the number left in front of x inside the bracket as the factor outside.', '{"question":"12x + 18 = ?(2x + 3). The number outside?","wrong_answer":"2","correct_answer":"6"}'::jsonb, 'Mixes up the factor with what is left.', 'The answer 2 as a wrong option, with a reason that names the idea.', 'The factor outside multiplies to give 12 and 18.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.FACTORISE_HCF.M_INSIDE_NUMBER_GIVEN', 'MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.FACTORISE_HCF', 'Gives the number left in the bracket as the factor outside.', '{"question":"12x + 18 = ?(2x + 3). The number outside?","wrong_answer":"3","correct_answer":"6"}'::jsonb, 'Reads the wrong number from the answer.', 'The answer 3 as a wrong option, with a reason that names the idea.', 'Outside × inside must give back each term.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.FACTORISE_HCF.M_FACTOR_ONE_TERM_ONLY', 'MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.FACTORISE_HCF', 'Divides only the first term by the factor.', '{"question":"Factorise 6x + 9","wrong_answer":"3(2x + 9)","correct_answer":"3(2x + 3)"}'::jsonb, 'Forgets the bracket multiplies every term.', 'The answer 3(2x + 9) as a wrong option, with a reason that names the idea.', 'Divide every term by 3.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.FACTORISE_HCF.M_ONE_LEFT_OUT', 'MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.FACTORISE_HCF', 'Leaves nothing in place of a term that equals the factor.', '{"question":"Factorise 5x + 5","wrong_answer":"5(x)","correct_answer":"5(x + 1)"}'::jsonb, 'Thinks a term divided by itself leaves nothing.', 'The answer 5(x) as a wrong option, with a reason that names the idea.', '5 ÷ 5 = 1: write the 1.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.FACTORISE_LETTERS.M_LETTER_FACTOR_MISSED', 'MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.FACTORISE_LETTERS', 'Takes out only the number when a letter is common too.', '{"question":"Factorise 3x² + 6x fully","wrong_answer":"3(x² + 2x)","correct_answer":"3x(x + 2)"}'::jsonb, 'Looks for common numbers only.', 'The answer 3(x² + 2x) as a wrong option, with a reason that names the idea.', 'Both terms have an x: take it out too.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.FACTORISE_LETTERS.M_POWER_NOT_REDUCED', 'MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.FACTORISE_LETTERS', 'Keeps the full power inside the bracket after taking out a letter.', '{"question":"Factorise 3x² + 6x","wrong_answer":"3x(x² + 2)","correct_answer":"3x(x + 2)"}'::jsonb, 'Does not divide the power.', 'The answer 3x(x² + 2) as a wrong option, with a reason that names the idea.', 'x² ÷ x = x.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.FACTORISE_LETTERS.M_UNLIKE_TERMS_COMBINED', 'MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.FACTORISE_LETTERS', 'Adds unlike terms into one before factorising.', '{"question":"Simplify 2x + 3y","wrong_answer":"5xy","correct_answer":"it cannot be simplified"}'::jsonb, 'Adds every number it sees.', 'The answer 5xy as a wrong option, with a reason that names the idea.', 'Only like terms can be added.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.FACTORISE_LETTERS.M_LETTER_ONE_LEFT_OUT', 'MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.FACTORISE_LETTERS', 'Leaves nothing for a term that is the factor itself.', '{"question":"Factorise x² + x","wrong_answer":"x(x)","correct_answer":"x(x + 1)"}'::jsonb, 'Thinks x ÷ x leaves nothing.', 'The answer x(x) as a wrong option, with a reason that names the idea.', 'x ÷ x = 1: write the 1.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.ALG_FRACTION_SIMPLIFY.M_ONLY_X_TERM_DIVIDED', 'MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.ALG_FRACTION_SIMPLIFY', 'Divides only the letter term of the top by the bottom.', '{"question":"Simplify (6x + 9)/3","wrong_answer":"2x + 9","correct_answer":"2x + 3"}'::jsonb, 'Forgets the bottom divides the whole top.', 'The answer 2x + 9 as a wrong option, with a reason that names the idea.', 'Every part of the top is divided by 3.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.ALG_FRACTION_SIMPLIFY.M_CANCEL_ACROSS_PLUS', 'MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.ALG_FRACTION_SIMPLIFY', 'Cancels a number that is only part of a sum on the top.', '{"question":"Simplify (x + 3)/3","wrong_answer":"x","correct_answer":"it cannot be simplified to x (it is x/3 + 1)"}'::jsonb, 'Cancels as if the top were a product.', 'The answer x as a wrong option, with a reason that names the idea.', 'Only common factors cancel; 3 is not a factor of x + 3.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.ALG_FRACTION_SIMPLIFY.M_CANCEL_LETTER_IN_SUM', 'MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.ALG_FRACTION_SIMPLIFY', 'Cancels a letter on the top with one on the bottom when the top is a sum.', '{"question":"Simplify (x + 2)/x","wrong_answer":"2","correct_answer":"1 + 2/x"}'::jsonb, 'Crosses out matching letters.', 'The answer 2 as a wrong option, with a reason that names the idea.', 'x is not a factor of the whole top.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.ALG_FRACTION_SIMPLIFY.M_NOT_FACTORISED_FIRST', 'MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.ALG_FRACTION_SIMPLIFY', 'Leaves a fraction unsimplified because the common bracket is hidden.', '{"question":"Simplify (4x + 8)/(x + 2)","wrong_answer":"(4x + 8)/(x + 2)","correct_answer":"4"}'::jsonb, 'Does not factorise the top.', 'The answer (4x + 8)/(x + 2) as a wrong option, with a reason that names the idea.', '4x + 8 = 4(x + 2): now cancel (x + 2).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.ALG_FRACTION_ADD_SUB.M_ALG_TOPS_BOTTOMS_ADDED', 'MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.ALG_FRACTION_ADD_SUB', 'Adds tops together and bottoms together.', '{"question":"x/2 + x/3","wrong_answer":"2x/5","correct_answer":"5x/6"}'::jsonb, 'Copies the rule for multiplying fractions.', 'The answer 2x/5 as a wrong option, with a reason that names the idea.', 'Use a common denominator, 6.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.ALG_FRACTION_ADD_SUB.M_DENOMINATOR_ONLY_CHANGED', 'MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.ALG_FRACTION_ADD_SUB', 'Changes the bottoms to the common denominator but not the tops.', '{"question":"x/2 + x/3","wrong_answer":"2x/6","correct_answer":"5x/6"}'::jsonb, 'Forgets each top must be multiplied too.', 'The answer 2x/6 as a wrong option, with a reason that names the idea.', 'x/2 = 3x/6 and x/3 = 2x/6.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.ALG_FRACTION_ADD_SUB.M_ALG_FRACTIONS_NOT_ADDABLE', 'MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.ALG_FRACTION_ADD_SUB', 'Believes algebraic fractions cannot be added.', '{"question":"Can x/2 + x/3 be written as one fraction?","wrong_answer":"No","correct_answer":"Yes: 5x/6"}'::jsonb, 'Thinks letters stop fractions being added.', 'The answer No as a wrong option, with a reason that names the idea.', 'They add like number fractions once the bottoms match.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.ALG_FRACTION_ADD_SUB.M_ALG_DENOMINATORS_ADDED', 'MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.ALG_FRACTION_ADD_SUB', 'Adds the bottom numbers when solving with fractions.', '{"question":"x/3 + x/4 = 7","wrong_answer":"x = 49","correct_answer":"x = 12"}'::jsonb, 'Treats x/3 + x/4 as x/7.', 'The answer x = 49 as a wrong option, with a reason that names the idea.', 'Common denominator 12: 7x/12 = 7.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.ALG_FRACTION_ADD_SUB.M_ONE_FRACTION_SOLVED', 'MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.ALG_FRACTION_ADD_SUB', 'Solves using only the first fraction.', '{"question":"x/3 + x/4 = 7","wrong_answer":"x = 21","correct_answer":"x = 12"}'::jsonb, 'Ignores the second term.', 'The answer x = 21 as a wrong option, with a reason that names the idea.', 'Both parts of the shamba count.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.ALG_FRACTION_ADD_SUB.M_LCM_MULTIPLIED_NOT_DIVIDED', 'MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.ALG_FRACTION_ADD_SUB', 'Multiplies both sides by the common denominator and stops.', '{"question":"x/3 + x/4 = 7","wrong_answer":"x = 84","correct_answer":"x = 12"}'::jsonb, 'Forgets that 7x is left, not x.', 'The answer x = 84 as a wrong option, with a reason that names the idea.', 'Times 12 gives 4x + 3x = 84, so 7x = 84.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.ALG_FRACTION_ADD_SUB.M_SUBTRACT_SIGN_NOT_SPREAD', 'MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.ALG_FRACTION_ADD_SUB', 'Takes away only the first term of a top that is subtracted.', '{"question":"x/2 - (x - 1)/3","wrong_answer":"(x - 2)/6","correct_answer":"(x + 2)/6"}'::jsonb, 'Leaves out the bracket.', 'The answer (x - 2)/6 as a wrong option, with a reason that names the idea.', '3x - 2(x - 1) = 3x - 2x + 2.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.SUBSTITUTE_POSITIVE.M_FIXED_TIMES_VARIABLE', 'MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.SUBSTITUTE_POSITIVE', 'Multiplies the whole expression by the value.', '{"question":"F = 50 + 30d; d = 6","wrong_answer":"480","correct_answer":"230"}'::jsonb, 'Puts the fixed amount and the rate together.', 'The answer 480 as a wrong option, with a reason that names the idea.', 'Only the 30d part uses the distance.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.SUBSTITUTE_POSITIVE.M_FIXED_PART_DROPPED', 'MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.SUBSTITUTE_POSITIVE', 'Leaves out the fixed charge.', '{"question":"F = 50 + 30d; d = 6","wrong_answer":"180","correct_answer":"230"}'::jsonb, 'Works only with the term that has the letter.', 'The answer 180 as a wrong option, with a reason that names the idea.', 'Add the fixed 50.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.SUBSTITUTE_POSITIVE.M_WRONG_TERM_MULTIPLIED', 'MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.SUBSTITUTE_POSITIVE', 'Multiplies the fixed amount by the value instead of the rate.', '{"question":"F = 50 + 30d; d = 6","wrong_answer":"330","correct_answer":"230"}'::jsonb, 'Attaches d to the first number.', 'The answer 330 as a wrong option, with a reason that names the idea.', 'd belongs to the 30.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.SUBSTITUTE_POSITIVE.M_COEFF_ADDED_NOT_MULTIPLIED', 'MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.SUBSTITUTE_POSITIVE', 'Adds the coefficient and the value, or writes them side by side.', '{"question":"3d when d = 4","wrong_answer":"7 or 34","correct_answer":"12"}'::jsonb, 'Does not read 3d as 3 × d.', 'The answer 7 or 34 as a wrong option, with a reason that names the idea.', 'A number next to a letter multiplies it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.SUBSTITUTE_POSITIVE.M_BRACKET_ORDER_WRONG', 'MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.SUBSTITUTE_POSITIVE', 'Adds before multiplying when evaluating.', '{"question":"2 + 3x when x = 4","wrong_answer":"20","correct_answer":"14"}'::jsonb, 'Works left to right.', 'The answer 20 as a wrong option, with a reason that names the idea.', 'Multiply first: 3 × 4, then add 2.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.SUBSTITUTE_NEGATIVE.M_NEGATIVE_SQUARED_NEGATIVE', 'MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.SUBSTITUTE_NEGATIVE', 'Gives a negative answer for a negative number squared.', '{"question":"m² when m = -3","wrong_answer":"-9","correct_answer":"9"}'::jsonb, 'Keeps the minus sign.', 'The answer -9 as a wrong option, with a reason that names the idea.', '(-3) × (-3) = 9.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.SUBSTITUTE_NEGATIVE.M_SQUARE_AS_TIMES_TWO', 'MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.SUBSTITUTE_NEGATIVE', 'Treats m² as 2 × m.', '{"question":"m² when m = -3","wrong_answer":"-6","correct_answer":"9"}'::jsonb, 'Reads the small 2 as times 2.', 'The answer -6 as a wrong option, with a reason that names the idea.', 'm² means m × m.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.SUBSTITUTE_NEGATIVE.M_COEFFICIENT_SQUARED', 'MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.SUBSTITUTE_NEGATIVE', 'Squares the coefficient as well as the letter.', '{"question":"2m² when m = -3","wrong_answer":"36","correct_answer":"18"}'::jsonb, 'Squares (2m).', 'The answer 36 as a wrong option, with a reason that names the idea.', 'Only m is squared: 2 × 9.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.SUBSTITUTE_NEGATIVE.M_MINUS_SIGN_DROPPED', 'MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.SUBSTITUTE_NEGATIVE', 'Adds a term that has a minus sign in front.', '{"question":"2m² - 3n when m = -3, n = 4","wrong_answer":"30","correct_answer":"6"}'::jsonb, 'Ignores the operation sign.', 'The answer 30 as a wrong option, with a reason that names the idea.', 'The sign in front of 3n is a minus.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.SUBSTITUTE_NEGATIVE.M_MINUS_MINUS_STAYS_MINUS', 'MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.SUBSTITUTE_NEGATIVE', 'Believes taking away a negative product keeps it negative.', '{"question":"10 - 4x when x = -2","wrong_answer":"2","correct_answer":"18"}'::jsonb, 'Thinks "minus times minus stays minus".', 'The answer 2 as a wrong option, with a reason that names the idea.', '4 × (-2) = -8; 10 - (-8) = 18.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.SUBSTITUTE_NEGATIVE.M_VALUE_SIGN_DROPPED', 'MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.SUBSTITUTE_NEGATIVE', 'Substitutes the size of a negative value and drops its minus sign.', '{"question":"10 - 4x when x = -2","wrong_answer":"2","correct_answer":"18"}'::jsonb, 'Thinks the sign is not part of the value.', 'The answer 2 as a wrong option, with a reason that names the idea.', 'x is -2, not 2: keep the sign in a bracket.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.SUBSTITUTE_NEGATIVE.M_VALUE_WRITTEN_BESIDE', 'MATH.G8.ALGEBR.ALGEBRAIC_EXPRESSIONS.SUBSTITUTE_NEGATIVE', 'Writes the negative value in place of x without multiplying.', '{"question":"10 - 4x when x = -2","wrong_answer":"10 - 4 - 2 = 4","correct_answer":"18"}'::jsonb, 'Replaces x by the digits and the sign.', 'The answer 10 - 4 - 2 = 4 as a wrong option, with a reason that names the idea.', 'Put the value in brackets: 4 × (-2).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.ALGEBR.LINEAR_EQUATIONS.FORM_SIMULTANEOUS.M_COEFFICIENTS_SWAPPED', 'MATH.G8.ALGEBR.LINEAR_EQUATIONS.FORM_SIMULTANEOUS', 'Puts the number of one item in front of the other item''s letter.', '{"question":"3 mandazi and 2 chapati cost 70. Equation?","wrong_answer":"2m + 3c = 70","correct_answer":"3m + 2c = 70"}'::jsonb, 'Writes the numbers in the order heard, not matched to items.', 'The answer 2m + 3c = 70 as a wrong option, with a reason that names the idea.', 'Each number goes with its own item.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.ALGEBR.LINEAR_EQUATIONS.FORM_SIMULTANEOUS.M_COUNTS_LEFT_OUT', 'MATH.G8.ALGEBR.LINEAR_EQUATIONS.FORM_SIMULTANEOUS', 'Leaves the numbers of items out of the equation.', '{"question":"3 mandazi and 2 chapati cost 70. Equation?","wrong_answer":"m + c = 70","correct_answer":"3m + 2c = 70"}'::jsonb, 'Writes the letters only.', 'The answer m + c = 70 as a wrong option, with a reason that names the idea.', 'The equation must say how many of each.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.ALGEBR.LINEAR_EQUATIONS.FORM_SIMULTANEOUS.M_TOTALS_ADDED', 'MATH.G8.ALGEBR.LINEAR_EQUATIONS.FORM_SIMULTANEOUS', 'Uses the sum of the two bills as the total of the second equation.', '{"question":"Bills of 70 and 110 for two orders. Second equation total?","wrong_answer":"180","correct_answer":"110"}'::jsonb, 'Thinks each new bill includes the last.', 'The answer 180 as a wrong option, with a reason that names the idea.', 'Each person pays their own total.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.ALGEBR.LINEAR_EQUATIONS.FORM_SIMULTANEOUS.M_MORE_THAN_SIGN_REVERSED', 'MATH.G8.ALGEBR.LINEAR_EQUATIONS.FORM_SIMULTANEOUS', 'Writes "x is 5 more than y" as y = x + 5.', '{"question":"The big bag is 5 kg heavier than the small bag (x big, y small)","wrong_answer":"y = x + 5","correct_answer":"x = y + 5"}'::jsonb, 'Writes the words in the order they come.', 'The answer y = x + 5 as a wrong option, with a reason that names the idea.', 'Add the 5 to the smaller one to make them equal.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.ALGEBR.LINEAR_EQUATIONS.FORM_SIMULTANEOUS.M_ONE_LETTER_FOR_BOTH', 'MATH.G8.ALGEBR.LINEAR_EQUATIONS.FORM_SIMULTANEOUS', 'Uses the same letter for two different unknowns.', '{"question":"Mandazi and chapati have different prices. Equation for 3 mandazi and 2 chapati costing 70?","wrong_answer":"5x = 70","correct_answer":"3m + 2c = 70"}'::jsonb, 'Thinks one letter stands for "the price".', 'The answer 5x = 70 as a wrong option, with a reason that names the idea.', 'Two different prices need two letters.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.ALGEBR.LINEAR_EQUATIONS.SOLVE_BY_SUBSTITUTION.M_SIGN_CHANGED_ON_SUBSTITUTING', 'MATH.G8.ALGEBR.LINEAR_EQUATIONS.SOLVE_BY_SUBSTITUTION', 'Changes the sign of a number when substituting the expression.', '{"question":"y = 2x - 3 into x + y = 9","wrong_answer":"x + 2x + 3 = 9","correct_answer":"x + 2x - 3 = 9"}'::jsonb, 'Copies the expression carelessly.', 'The answer x + 2x + 3 = 9 as a wrong option, with a reason that names the idea.', 'Put the whole expression in a bracket: x + (2x - 3).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.ALGEBR.LINEAR_EQUATIONS.SOLVE_BY_SUBSTITUTION.M_SUBSTITUTED_INTO_SAME', 'MATH.G8.ALGEBR.LINEAR_EQUATIONS.SOLVE_BY_SUBSTITUTION', 'Substitutes the expression back into the equation it came from.', '{"question":"y = 2x - 3 and x + y = 9: put y = 2x - 3 into y = 2x - 3","wrong_answer":"0 = 0","correct_answer":"put it into x + y = 9"}'::jsonb, 'Loses track of which equation was used.', 'The answer 0 = 0 as a wrong option, with a reason that names the idea.', 'Substitute into the other equation.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.ALGEBR.LINEAR_EQUATIONS.SOLVE_BY_SUBSTITUTION.M_BRACKET_NOT_EXPANDED', 'MATH.G8.ALGEBR.LINEAR_EQUATIONS.SOLVE_BY_SUBSTITUTION', 'Multiplies only the first term of the bracket after substituting.', '{"question":"2x + 3y = 13 with y = x - 1","wrong_answer":"2x + 3x - 1 = 13","correct_answer":"2x + 3x - 3 = 13"}'::jsonb, 'Forgets the 3 multiplies every term.', 'The answer 2x + 3x - 1 = 13 as a wrong option, with a reason that names the idea.', '3(x - 1) = 3x - 3.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.ALGEBR.LINEAR_EQUATIONS.SOLVE_BY_SUBSTITUTION.M_ONLY_ONE_FOUND', 'MATH.G8.ALGEBR.LINEAR_EQUATIONS.SOLVE_BY_SUBSTITUTION', 'Stops after finding one unknown.', '{"question":"y = 2x - 3 and x + y = 9. Solve.","wrong_answer":"x = 4","correct_answer":"x = 4, y = 5"}'::jsonb, 'Thinks one value is the answer.', 'The answer x = 4 as a wrong option, with a reason that names the idea.', 'Substitute back for the other unknown.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.ALGEBR.LINEAR_EQUATIONS.SOLVE_BY_ELIMINATION.M_ADDED_INSTEAD_OF_SUBTRACTED', 'MATH.G8.ALGEBR.LINEAR_EQUATIONS.SOLVE_BY_ELIMINATION', 'Adds the equations when the matching terms have the same sign.', '{"question":"2x + y = 7 and 2x + 3y = 13: eliminate x","wrong_answer":"4x + 4y = 20","correct_answer":"2y = 6"}'::jsonb, 'Always adds the equations.', 'The answer 4x + 4y = 20 as a wrong option, with a reason that names the idea.', 'Same sign: subtract to cancel.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.ALGEBR.LINEAR_EQUATIONS.SOLVE_BY_ELIMINATION.M_NOT_DIVIDED_BY_COEFFICIENT', 'MATH.G8.ALGEBR.LINEAR_EQUATIONS.SOLVE_BY_ELIMINATION', 'Stops at the number of lots of the unknown without dividing.', '{"question":"2y = 6","wrong_answer":"y = 6","correct_answer":"y = 3"}'::jsonb, 'Forgets the 2 in front.', 'The answer y = 6 as a wrong option, with a reason that names the idea.', 'Divide both sides by 2.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.ALGEBR.LINEAR_EQUATIONS.SOLVE_BY_ELIMINATION.M_TERM_FOR_UNKNOWN', 'MATH.G8.ALGEBR.LINEAR_EQUATIONS.SOLVE_BY_ELIMINATION', 'Gives the value of a term (2x) as the value of the unknown.', '{"question":"2x + 3 = 7","wrong_answer":"x = 4","correct_answer":"x = 2"}'::jsonb, 'Stops once the term is alone.', 'The answer x = 4 as a wrong option, with a reason that names the idea.', 'That is 2x: divide by 2.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.ALGEBR.LINEAR_EQUATIONS.SOLVE_BY_ELIMINATION.M_ELIMINATION_TO_SHRINK', 'MATH.G8.ALGEBR.LINEAR_EQUATIONS.SOLVE_BY_ELIMINATION', 'Believes elimination is done to make the numbers smaller.', '{"question":"Why subtract 2x + y = 7 from 2x + 3y = 13?","wrong_answer":"to make the numbers smaller","correct_answer":"so the x terms cancel"}'::jsonb, 'Does not see the aim of removing an unknown.', 'The answer to make the numbers smaller as a wrong option, with a reason that names the idea.', 'The aim is one equation with one unknown.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.ALGEBR.LINEAR_EQUATIONS.SOLVE_BY_ELIMINATION.M_ONE_STEP_BOTH', 'MATH.G8.ALGEBR.LINEAR_EQUATIONS.SOLVE_BY_ELIMINATION', 'Expects elimination to give both unknowns at once.', '{"question":"After subtracting, what do you find first?","wrong_answer":"x and y together","correct_answer":"y, then x by substituting"}'::jsonb, 'Thinks one step solves everything.', 'The answer x and y together as a wrong option, with a reason that names the idea.', 'One unknown disappears; find the other first.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.ALGEBR.LINEAR_EQUATIONS.SOLVE_BY_ELIMINATION.M_ALWAYS_SUBTRACT', 'MATH.G8.ALGEBR.LINEAR_EQUATIONS.SOLVE_BY_ELIMINATION', 'Believes you always subtract to eliminate.', '{"question":"x + y = 10 and x - y = 4: eliminate y","wrong_answer":"subtract: 2y = 6","correct_answer":"add: 2x = 14"}'::jsonb, 'Learnt one case only.', 'The answer subtract: 2y = 6 as a wrong option, with a reason that names the idea.', 'Opposite signs: add to cancel.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.ALGEBR.LINEAR_EQUATIONS.SOLVE_BY_ELIMINATION.M_EQUAL_SPLIT_ASSUMED', 'MATH.G8.ALGEBR.LINEAR_EQUATIONS.SOLVE_BY_ELIMINATION', 'Shares a total equally as if the two unknowns were the same.', '{"question":"x + y = 50 and x - y = 6","wrong_answer":"x = 25","correct_answer":"x = 28"}'::jsonb, 'Ignores the second equation.', 'The answer x = 25 as a wrong option, with a reason that names the idea.', 'The difference matters: add the equations.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.ALGEBR.LINEAR_EQUATIONS.ELIMINATION_MAKE_EQUAL.M_ONLY_ONE_TERM_MULTIPLIED', 'MATH.G8.ALGEBR.LINEAR_EQUATIONS.ELIMINATION_MAKE_EQUAL', 'Multiplies only one term of the equation.', '{"question":"Multiply x + y = 5 by 2","wrong_answer":"2x + y = 5","correct_answer":"2x + 2y = 10"}'::jsonb, 'Changes the term it wants to match.', 'The answer 2x + y = 5 as a wrong option, with a reason that names the idea.', 'Every term, both sides.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.ALGEBR.LINEAR_EQUATIONS.ELIMINATION_MAKE_EQUAL.M_RIGHT_SIDE_NOT_MULTIPLIED', 'MATH.G8.ALGEBR.LINEAR_EQUATIONS.ELIMINATION_MAKE_EQUAL', 'Multiplies the left side but not the total.', '{"question":"Multiply x + y = 5 by 2","wrong_answer":"2x + 2y = 5","correct_answer":"2x + 2y = 10"}'::jsonb, 'Forgets the equation must stay balanced.', 'The answer 2x + 2y = 5 as a wrong option, with a reason that names the idea.', 'The right side is multiplied too.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.ALGEBR.LINEAR_EQUATIONS.ELIMINATION_MAKE_EQUAL.M_WRONG_MULTIPLIER', 'MATH.G8.ALGEBR.LINEAR_EQUATIONS.ELIMINATION_MAKE_EQUAL', 'Multiplies by a number that does not make the coefficients equal.', '{"question":"3x + 2y = 16 and x + y = 6: make the x terms equal","wrong_answer":"multiply the second by 2","correct_answer":"multiply the second by 3"}'::jsonb, 'Picks a number from the other unknown.', 'The answer multiply the second by 2 as a wrong option, with a reason that names the idea.', 'Match 3x: multiply the second equation by 3.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.ALGEBR.LINEAR_EQUATIONS.ELIMINATION_MAKE_EQUAL.M_SIGNS_IN_SUBTRACTION', 'MATH.G8.ALGEBR.LINEAR_EQUATIONS.ELIMINATION_MAKE_EQUAL', 'Subtracts a negative term wrongly.', '{"question":"(3x + 2y) - (3x - 4y)","wrong_answer":"-2y","correct_answer":"6y"}'::jsonb, 'Takes 4 from 2 without the sign.', 'The answer -2y as a wrong option, with a reason that names the idea.', '2y - (-4y) = 6y.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.ALGEBR.LINEAR_EQUATIONS.SIMULTANEOUS_IN_CONTEXT.M_DIFFERENCE_NOT_SHARED', 'MATH.G8.ALGEBR.LINEAR_EQUATIONS.SIMULTANEOUS_IN_CONTEXT', 'Gives the cost of the extra items as the price of one.', '{"question":"1 adult and 4 children pay 700; 3 adults and 4 children pay 1,300. One adult?","wrong_answer":"600","correct_answer":"300"}'::jsonb, 'Forgets the extra is for 2 adults.', 'The answer 600 as a wrong option, with a reason that names the idea.', 'Share 600 between the 2 extra adults.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.ALGEBR.LINEAR_EQUATIONS.SIMULTANEOUS_IN_CONTEXT.M_TOTAL_SHARED_EQUALLY', 'MATH.G8.ALGEBR.LINEAR_EQUATIONS.SIMULTANEOUS_IN_CONTEXT', 'Shares a total equally among people who pay different prices.', '{"question":"1 adult and 4 children pay 700. One adult?","wrong_answer":"140","correct_answer":"300"}'::jsonb, 'Treats everyone as paying the same.', 'The answer 140 as a wrong option, with a reason that names the idea.', 'Adults and children pay different prices.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.ALGEBR.LINEAR_EQUATIONS.SIMULTANEOUS_IN_CONTEXT.M_OTHER_UNKNOWN_GIVEN', 'MATH.G8.ALGEBR.LINEAR_EQUATIONS.SIMULTANEOUS_IN_CONTEXT', 'Gives the value of the other unknown.', '{"question":"Solving gives a = 300 and c = 100, where a is the adult price. One adult ticket?","wrong_answer":"100","correct_answer":"300"}'::jsonb, 'Answers with the last value found.', 'The answer 100 as a wrong option, with a reason that names the idea.', 'Read the question again: which one is asked?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.ALGEBR.LINEAR_EQUATIONS.SIMULTANEOUS_IN_CONTEXT.M_OTHER_GROUP_IGNORED', 'MATH.G8.ALGEBR.LINEAR_EQUATIONS.SIMULTANEOUS_IN_CONTEXT', 'Divides a group total by one kind of person only.', '{"question":"1 adult and 4 children pay 700. One adult?","wrong_answer":"700","correct_answer":"300"}'::jsonb, 'Forgets the children in the group pay too.', 'The answer 700 as a wrong option, with a reason that names the idea.', 'Take the children''s cost away first.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.ALGEBR.LINEAR_EQUATIONS.SIMULTANEOUS_IN_CONTEXT.M_ALL_ONE_KIND', 'MATH.G8.ALGEBR.LINEAR_EQUATIONS.SIMULTANEOUS_IN_CONTEXT', 'Assumes every coin or animal is of one kind.', '{"question":"20 coins of sh 5 and sh 10 worth sh 150. How many sh 10 coins?","wrong_answer":"15","correct_answer":"10"}'::jsonb, 'Divides the total value by one coin value.', 'The answer 15 as a wrong option, with a reason that names the idea.', 'Some coins are sh 5: use both equations.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.ALGEBR.LINEAR_EQUATIONS.SIMULTANEOUS_IN_CONTEXT.M_DOUBLED_AS_ADD_TWO', 'MATH.G8.ALGEBR.LINEAR_EQUATIONS.SIMULTANEOUS_IN_CONTEXT', 'Adds 2 to an equation instead of multiplying it by 2.', '{"question":"h + g = 30, times 2","wrong_answer":"h + g + 2 = 32","correct_answer":"2h + 2g = 60"}'::jsonb, 'Confuses doubling with adding two.', 'The answer h + g + 2 = 32 as a wrong option, with a reason that names the idea.', 'Double every term: 2h + 2g = 60.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.MEASUR.CIRCLES.CIRCUMFERENCE_RADIUS_DIAMETER.M_RADIUS_FOR_DIAMETER', 'MATH.G8.MEASUR.CIRCLES.CIRCUMFERENCE_RADIUS_DIAMETER', 'Uses the radius in C = πd.', '{"question":"Circumference of a circle of radius 14 cm","wrong_answer":"44 cm","correct_answer":"88 cm"}'::jsonb, 'Forgets that d is twice r.', 'The answer 44 cm as a wrong option, with a reason that names the idea.', 'Double the radius, or use 2πr.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.MEASUR.CIRCLES.CIRCUMFERENCE_RADIUS_DIAMETER.M_AREA_FOR_CIRCUMFERENCE', 'MATH.G8.MEASUR.CIRCLES.CIRCUMFERENCE_RADIUS_DIAMETER', 'Squares the radius, finding the area instead.', '{"question":"Circumference of a circle of radius 7 cm","wrong_answer":"154 cm","correct_answer":"44 cm"}'::jsonb, 'Mixes up the two circle formulas.', 'The answer 154 cm as a wrong option, with a reason that names the idea.', 'Distance round: 2πr. Space inside: πr².', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.MEASUR.CIRCLES.CIRCUMFERENCE_RADIUS_DIAMETER.M_PI_ADDED', 'MATH.G8.MEASUR.CIRCLES.CIRCUMFERENCE_RADIUS_DIAMETER', 'Adds π to the radius or diameter.', '{"question":"Circumference with a diameter of 14 cm","wrong_answer":"17.14 cm","correct_answer":"44 cm"}'::jsonb, 'Does not know π is a multiplier.', 'The answer 17.14 cm as a wrong option, with a reason that names the idea.', 'C = π × d.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.MEASUR.CIRCLES.CIRCUMFERENCE_RADIUS_DIAMETER.M_DIVIDED_BY_PI', 'MATH.G8.MEASUR.CIRCLES.CIRCUMFERENCE_RADIUS_DIAMETER', 'Divides the diameter by π.', '{"question":"Circumference with a diameter of 14 cm","wrong_answer":"4.45 cm","correct_answer":"44 cm"}'::jsonb, 'Goes the wrong way between across and round.', 'The answer 4.45 cm as a wrong option, with a reason that names the idea.', 'The distance round is longer than across: multiply.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
