INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.MEASUR.MONEY.COMPOUND_INTEREST.M_YEAR_INTEREST_NOT_ADDED', 'MATH.G8.MEASUR.MONEY.COMPOUND_INTEREST', 'Gives the year''s interest as the amount at the end of the year.', '{"question":"Start of year 2: 11,000 at 10%. Amount at the end of year 2?","wrong_answer":"1,100","correct_answer":"12,100"}'::jsonb, 'Forgets to add the interest on.', 'The answer 1,100 as a wrong option, with a reason that names the idea.', 'Add it to the 11,000.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.MEASUR.MONEY.COMPOUND_INTEREST.M_HIGHER_RATE_ASSUMED', 'MATH.G8.MEASUR.MONEY.COMPOUND_INTEREST', 'Believes compound interest ends higher because its rate is higher.', '{"question":"Both pay 10%. Why does compound end with more?","wrong_answer":"a higher rate","correct_answer":"interest earns interest"}'::jsonb, 'Looks for a difference in the numbers.', 'The answer a higher rate as a wrong option, with a reason that names the idea.', 'The rate is the same; the interest is added and earns interest.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.MEASUR.MONEY.COMPOUND_INTEREST.M_SIMPLE_ONCE_ONLY', 'MATH.G8.MEASUR.MONEY.COMPOUND_INTEREST', 'Believes simple interest is paid only in the first year.', '{"question":"Simple interest of 10% on 10,000 for 3 years. Interest?","wrong_answer":"1,000","correct_answer":"3,000"}'::jsonb, 'Thinks "simple" means one payment.', 'The answer 1,000 as a wrong option, with a reason that names the idea.', 'Simple interest is paid every year, on the first amount.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.MEASUR.MONEY.COMPOUND_INTEREST.M_COMPOUND_MEANS_MONTHLY', 'MATH.G8.MEASUR.MONEY.COMPOUND_INTEREST', 'Believes compound means the interest is paid each month.', '{"question":"Is compound interest paid monthly?","wrong_answer":"yes, always","correct_answer":"it depends on the account; the difference is what it is worked on"}'::jsonb, 'Confuses how often with what the interest is on.', 'The answer yes, always as a wrong option, with a reason that names the idea.', 'Compound means the interest is worked on the growing amount.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.MEASUR.MONEY.DEPRECIATION.M_DEPRECIATION_ON_FIRST_PRICE', 'MATH.G8.MEASUR.MONEY.DEPRECIATION', 'Takes the percentage off the new price every year.', '{"question":"120,000 losing 20% a year. Value after 2 years?","wrong_answer":"72,000","correct_answer":"76,800"}'::jsonb, 'Uses simple depreciation.', 'The answer 72,000 as a wrong option, with a reason that names the idea.', 'Year 2 loses 20% of 96,000.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.MEASUR.MONEY.DEPRECIATION.M_ONE_YEAR_ONLY_DEP', 'MATH.G8.MEASUR.MONEY.DEPRECIATION', 'Gives the value after one year.', '{"question":"120,000 losing 20% a year. Value after 2 years?","wrong_answer":"96,000","correct_answer":"76,800"}'::jsonb, 'Stops after the first year.', 'The answer 96,000 as a wrong option, with a reason that names the idea.', 'Repeat for year 2.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.MEASUR.MONEY.DEPRECIATION.M_LOSS_FOR_VALUE', 'MATH.G8.MEASUR.MONEY.DEPRECIATION', 'Gives the value lost when the value left is asked.', '{"question":"120,000 losing 20% a year. Value after 2 years?","wrong_answer":"43,200","correct_answer":"76,800"}'::jsonb, 'Answers the loss.', 'The answer 43,200 as a wrong option, with a reason that names the idea.', 'Value left = price - loss.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.MEASUR.MONEY.DEPRECIATION.M_SAME_AMOUNT_EACH_YEAR', 'MATH.G8.MEASUR.MONEY.DEPRECIATION', 'Takes the same amount off each year as in the first year.', '{"question":"Fridge: 40,000, then 32,000. Same per cent each year. After 3 years?","wrong_answer":"16,000","correct_answer":"20,480"}'::jsonb, 'Sees the first fall and repeats it.', 'The answer 16,000 as a wrong option, with a reason that names the idea.', 'The same per cent of a smaller value is a smaller fall.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.MEASUR.MONEY.DEPRECIATION.M_LAST_FALL_REPEATED', 'MATH.G8.MEASUR.MONEY.DEPRECIATION', 'Repeats the previous year''s fall instead of working the new one.', '{"question":"40,000, 32,000, 25,600. After 3 years?","wrong_answer":"19,200","correct_answer":"20,480"}'::jsonb, 'Takes off 6,400 again.', 'The answer 19,200 as a wrong option, with a reason that names the idea.', '20% of 25,600 is 5,120.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.MEASUR.MONEY.DEPRECIATION.M_SECOND_FROM_BIGGER', 'MATH.G8.MEASUR.MONEY.DEPRECIATION', 'Believes the second year''s percentage is taken from a bigger value, so the total loss is more than the two per cents added.', '{"question":"A phone loses 20% then another 20%. Total loss?","wrong_answer":"44%","correct_answer":"36%"}'::jsonb, 'Mixes up depreciation with compound growth.', 'The answer 44% as a wrong option, with a reason that names the idea.', 'After a fall the value is smaller: 20% of 80% is 16%, so 20 + 16 = 36%.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
