INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.MEASUR.MONEY.APPRECIATION.M_APPRECIATION_SUBTRACTED', 'MATH.G8.MEASUR.MONEY.APPRECIATION', 'Takes the percentage off for an item that appreciates.', '{"question":"Land of 500,000 appreciates 10% a year. After 1 year?","wrong_answer":"450,000","correct_answer":"550,000"}'::jsonb, 'Confuses appreciate and depreciate.', 'The answer 450,000 as a wrong option, with a reason that names the idea.', 'Appreciate means the value goes up.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.MEASUR.MONEY.APPRECIATION.M_APPRECIATION_ON_FIRST_VALUE', 'MATH.G8.MEASUR.MONEY.APPRECIATION', 'Adds the percentage of the first value every year.', '{"question":"Land of 500,000 at 10% a year. After 2 years?","wrong_answer":"600,000","correct_answer":"605,000"}'::jsonb, 'Uses simple growth.', 'The answer 600,000 as a wrong option, with a reason that names the idea.', 'Year 2 adds 10% of 550,000.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
