INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.MEASUR.MONEY.APPRECIATION.M_WHAT_APPRECIATES', 'MATH.G8.MEASUR.MONEY.APPRECIATION', 'Believes vehicles and phones usually gain value and land loses it.', '{"question":"Which usually appreciates: a phone or a plot of land?","wrong_answer":"a phone","correct_answer":"a plot of land"}'::jsonb, 'Thinks new things are worth more.', 'The answer a phone as a wrong option, with a reason that names the idea.', 'Most goods lose value with use; land in a growing town usually gains.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
