INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.GEOMET.GEOMETRICAL_CONSTRUCTION.CONSTRUCT_PARALLEL_PERPENDICULAR.M_PERPENDICULAR_BY_EYE', 'MATH.G8.GEOMET.GEOMETRICAL_CONSTRUCTION.CONSTRUCT_PARALLEL_PERPENDICULAR', 'Draws a perpendicular by eye with a ruler instead of constructing it.', '{"question":"How do you draw a perpendicular with ruler and compasses?","wrong_answer":"line up the ruler so it looks straight","correct_answer":"arcs from the point, then join the crossing"}'::jsonb, 'Thinks looking right is enough.', 'The answer line up the ruler so it looks straight as a wrong option, with a reason that names the idea.', 'A construction uses compass arcs so the right angle is exact.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
