INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.GEOMET.GEOMETRICAL_CONSTRUCTION.CONSTRUCT_PARALLEL_PERPENDICULAR.M_PERPENDICULAR_FOOT_AT_MIDPOINT', 'MATH.G8.GEOMET.GEOMETRICAL_CONSTRUCTION.CONSTRUCT_PARALLEL_PERPENDICULAR', 'Assumes the perpendicular from a point meets the line at its midpoint.', '{"question":"A perpendicular from P (not above the middle) to AB: where does it meet AB?","wrong_answer":"at the midpoint of AB","correct_answer":"directly below P"}'::jsonb, 'Mixes it up with the perpendicular bisector.', 'The answer at the midpoint of AB as a wrong option, with a reason that names the idea.', 'The foot is where the arcs from P cut AB, bisected again.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.GEOMET.GEOMETRICAL_CONSTRUCTION.DIVIDE_LINE_METHOD.M_RATIO_PARTS_MULTIPLIED', 'MATH.G8.GEOMET.GEOMETRICAL_CONSTRUCTION.DIVIDE_LINE_METHOD', 'Multiplies the ratio numbers to get the number of equal parts.', '{"question":"Divide AB in the ratio 2 : 3. Equal parts on the ray?","wrong_answer":"6","correct_answer":"5"}'::jsonb, 'Multiplies the two numbers in the ratio.', 'The answer 6 as a wrong option, with a reason that names the idea.', 'Add the parts: 2 + 3.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.GEOMET.GEOMETRICAL_CONSTRUCTION.DIVIDE_LINE_METHOD.M_FIRST_PART_ONLY', 'MATH.G8.GEOMET.GEOMETRICAL_CONSTRUCTION.DIVIDE_LINE_METHOD', 'Marks only the first ratio number of parts.', '{"question":"Ratio 2 : 3. Equal parts on the ray?","wrong_answer":"2","correct_answer":"5"}'::jsonb, 'Thinks only one part is drawn.', 'The answer 2 as a wrong option, with a reason that names the idea.', 'The ray holds both parts.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.GEOMET.GEOMETRICAL_CONSTRUCTION.DIVIDE_LINE_METHOD.M_SECOND_PART_ONLY', 'MATH.G8.GEOMET.GEOMETRICAL_CONSTRUCTION.DIVIDE_LINE_METHOD', 'Marks only the second ratio number of parts.', '{"question":"Ratio 2 : 3. Equal parts on the ray?","wrong_answer":"3","correct_answer":"5"}'::jsonb, 'Thinks only one part is drawn.', 'The answer 3 as a wrong option, with a reason that names the idea.', 'The ray holds both parts.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.GEOMET.GEOMETRICAL_CONSTRUCTION.DIVIDE_LINE_METHOD.M_PARALLEL_SAME_LENGTH', 'MATH.G8.GEOMET.GEOMETRICAL_CONSTRUCTION.DIVIDE_LINE_METHOD', 'Believes the parallel lines matter because they are as long as AB.', '{"question":"Why must the lines be parallel?","wrong_answer":"they are as long as AB","correct_answer":"parallel lines cut AB in the same ratio as the ray"}'::jsonb, 'Thinks parallel means equal.', 'The answer they are as long as AB as a wrong option, with a reason that names the idea.', 'What matters is where they cut AB.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.GEOMET.GEOMETRICAL_CONSTRUCTION.DIVIDE_LINE_METHOD.M_PARALLEL_AS_PERPENDICULAR', 'MATH.G8.GEOMET.GEOMETRICAL_CONSTRUCTION.DIVIDE_LINE_METHOD', 'Believes parallel lines make right angles with AB.', '{"question":"Why must the lines be parallel?","wrong_answer":"they make right angles with AB","correct_answer":"they cut AB in the same ratio"}'::jsonb, 'Mixes parallel and perpendicular.', 'The answer they make right angles with AB as a wrong option, with a reason that names the idea.', 'Parallel lines keep the same slope as the line to B.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.GEOMET.GEOMETRICAL_CONSTRUCTION.DIVIDE_LINE_METHOD.M_PARALLEL_PURPOSE_UNKNOWN', 'MATH.G8.GEOMET.GEOMETRICAL_CONSTRUCTION.DIVIDE_LINE_METHOD', 'Gives a reason for the parallel lines that has nothing to do with the ratio.', '{"question":"Why must the lines be parallel?","wrong_answer":"to stop the compasses slipping","correct_answer":"they carry the equal parts over to AB"}'::jsonb, 'Does not know what each step does.', 'The answer to stop the compasses slipping as a wrong option, with a reason that names the idea.', 'The parallel lines carry the equal parts over to AB.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.GEOMET.GEOMETRICAL_CONSTRUCTION.DIVIDE_LINE_LENGTHS.M_LENGTH_MINUS_PARTS', 'MATH.G8.GEOMET.GEOMETRICAL_CONSTRUCTION.DIVIDE_LINE_LENGTHS', 'Takes the ratio numbers away from the length.', '{"question":"A 15 cm line in the ratio 2 : 3. Each equal part?","wrong_answer":"10 cm","correct_answer":"3 cm"}'::jsonb, 'Subtracts the numbers.', 'The answer 10 cm as a wrong option, with a reason that names the idea.', 'Divide the length by the 5 parts.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.GEOMET.GEOMETRICAL_CONSTRUCTION.DIVIDE_LINE_LENGTHS.M_LENGTH_TIMES_PARTS', 'MATH.G8.GEOMET.GEOMETRICAL_CONSTRUCTION.DIVIDE_LINE_LENGTHS', 'Multiplies the length by the number of parts.', '{"question":"A 15 cm line in the ratio 2 : 3. Each equal part?","wrong_answer":"75 cm","correct_answer":"3 cm"}'::jsonb, 'Uses the wrong operation.', 'The answer 75 cm as a wrong option, with a reason that names the idea.', 'A part is smaller than the line: divide.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.GEOMET.GEOMETRICAL_CONSTRUCTION.DIVIDE_LINE_LENGTHS.M_PARTS_ORDER_SWAPPED', 'MATH.G8.GEOMET.GEOMETRICAL_CONSTRUCTION.DIVIDE_LINE_LENGTHS', 'Gives the part for the other end of the line.', '{"question":"A 15 cm line in the ratio 2 : 3 from A. Part next to A?","wrong_answer":"9 cm","correct_answer":"6 cm"}'::jsonb, 'Does not match the ratio order to the ends.', 'The answer 9 cm as a wrong option, with a reason that names the idea.', 'The first number goes with A.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.GEOMET.GEOMETRICAL_CONSTRUCTION.DIVIDE_LINE_LENGTHS.M_WHOLE_LINE_GIVEN', 'MATH.G8.GEOMET.GEOMETRICAL_CONSTRUCTION.DIVIDE_LINE_LENGTHS', 'Gives the whole line as a part.', '{"question":"A 15 cm line in the ratio 2 : 3 from A. Part next to A?","wrong_answer":"15 cm","correct_answer":"6 cm"}'::jsonb, 'Answers with the length given.', 'The answer 15 cm as a wrong option, with a reason that names the idea.', 'The part is 2 of the 5 equal parts.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.GEOMET.GEOMETRICAL_CONSTRUCTION.POLYGON_ANGLE_PROPERTIES.M_EXTERIOR_FOR_INTERIOR', 'MATH.G8.GEOMET.GEOMETRICAL_CONSTRUCTION.POLYGON_ANGLE_PROPERTIES', 'Gives the exterior angle when the interior angle is asked.', '{"question":"Interior angle of a regular pentagon","wrong_answer":"72°","correct_answer":"108°"}'::jsonb, 'Remembers 360 ÷ n.', 'The answer 72° as a wrong option, with a reason that names the idea.', 'Interior = 180° - exterior.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.GEOMET.GEOMETRICAL_CONSTRUCTION.POLYGON_ANGLE_PROPERTIES.M_SUM_FOR_ONE_ANGLE', 'MATH.G8.GEOMET.GEOMETRICAL_CONSTRUCTION.POLYGON_ANGLE_PROPERTIES', 'Gives the angle sum when one angle is asked.', '{"question":"Interior angle of a regular hexagon","wrong_answer":"720°","correct_answer":"120°"}'::jsonb, 'Stops at the sum.', 'The answer 720° as a wrong option, with a reason that names the idea.', 'Share the sum among the 6 angles.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.GEOMET.GEOMETRICAL_CONSTRUCTION.POLYGON_ANGLE_PROPERTIES.M_SUM_AS_N_TIMES_180', 'MATH.G8.GEOMET.GEOMETRICAL_CONSTRUCTION.POLYGON_ANGLE_PROPERTIES', 'Uses n × 180° for the angle sum.', '{"question":"Angle sum of a pentagon","wrong_answer":"900°","correct_answer":"540°"}'::jsonb, 'Forgets the "minus 2".', 'The answer 900° as a wrong option, with a reason that names the idea.', 'A pentagon splits into 3 triangles: (5 - 2) × 180°.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.GEOMET.GEOMETRICAL_CONSTRUCTION.POLYGON_ANGLE_PROPERTIES.M_RIGHT_ANGLES_COUNT_WRONG', 'MATH.G8.GEOMET.GEOMETRICAL_CONSTRUCTION.POLYGON_ANGLE_PROPERTIES', 'Says a polygon''s angles add to as many right angles as it has sides.', '{"question":"Angle sum of a hexagon in right angles","wrong_answer":"6 right angles","correct_answer":"8 right angles"}'::jsonb, 'Links each side to one right angle.', 'The answer 6 right angles as a wrong option, with a reason that names the idea.', 'The sum is (2n - 4) right angles.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.GEOMET.GEOMETRICAL_CONSTRUCTION.POLYGON_ANGLE_PROPERTIES.M_EXTERIOR_SUM_GROWS', 'MATH.G8.GEOMET.GEOMETRICAL_CONSTRUCTION.POLYGON_ANGLE_PROPERTIES', 'Believes the exterior angles add to more as the number of sides grows.', '{"question":"Sum of the exterior angles of an octagon","wrong_answer":"1,080°","correct_answer":"360°"}'::jsonb, 'Expects every sum to grow.', 'The answer 1,080° as a wrong option, with a reason that names the idea.', 'Walking round any polygon is one full turn: 360°.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.GEOMET.GEOMETRICAL_CONSTRUCTION.CONSTRUCT_REGULAR_POLYGON.M_EQUAL_SIDES_ENOUGH', 'MATH.G8.GEOMET.GEOMETRICAL_CONSTRUCTION.CONSTRUCT_REGULAR_POLYGON', 'Believes equal sides alone make a polygon regular.', '{"question":"A rhombus with sides of 5 cm: is it a regular polygon?","wrong_answer":"Yes","correct_answer":"No, its angles are not all equal"}'::jsonb, 'Forgets the angles.', 'The answer Yes as a wrong option, with a reason that names the idea.', 'Regular means equal sides and equal angles.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.GEOMET.GEOMETRICAL_CONSTRUCTION.CONSTRUCT_REGULAR_POLYGON.M_CENTRE_ANGLE_AT_CORNER', 'MATH.G8.GEOMET.GEOMETRICAL_CONSTRUCTION.CONSTRUCT_REGULAR_POLYGON', 'Uses 360° ÷ n as the angle at each corner of the polygon.', '{"question":"Angle at each corner of a regular pentagon","wrong_answer":"72°","correct_answer":"108°"}'::jsonb, 'Mixes the centre angle with the corner angle.', 'The answer 72° as a wrong option, with a reason that names the idea.', '72° is at the centre; each corner is 108°.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.GEOMET.GEOMETRICAL_CONSTRUCTION.CONSTRUCT_REGULAR_POLYGON.M_HEXAGON_SIDE_NOT_RADIUS', 'MATH.G8.GEOMET.GEOMETRICAL_CONSTRUCTION.CONSTRUCT_REGULAR_POLYGON', 'Does not know a regular hexagon''s side equals the radius of its circle.', '{"question":"A regular hexagon in a circle of radius 4 cm: side?","wrong_answer":"8 cm","correct_answer":"4 cm"}'::jsonb, 'Uses the diameter.', 'The answer 8 cm as a wrong option, with a reason that names the idea.', 'Six equilateral triangles meet at the centre: side = radius.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.GEOMET.GEOMETRICAL_CONSTRUCTION.CONSTRUCT_REGULAR_POLYGON.M_INTERIOR_AT_CENTRE', 'MATH.G8.GEOMET.GEOMETRICAL_CONSTRUCTION.CONSTRUCT_REGULAR_POLYGON', 'Uses the interior angle at the centre of the circle.', '{"question":"Angle at the centre between corners of a regular hexagon","wrong_answer":"120°","correct_answer":"60°"}'::jsonb, 'Uses the angle remembered for a hexagon.', 'The answer 120° as a wrong option, with a reason that names the idea.', 'At the centre: 360° ÷ 6.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.GEOMET.GEOMETRICAL_CONSTRUCTION.CONSTRUCT_IRREGULAR_POLYGON.M_SIDES_ORDER_WRONG', 'MATH.G8.GEOMET.GEOMETRICAL_CONSTRUCTION.CONSTRUCT_IRREGULAR_POLYGON', 'Draws the sides in a different order from the one given.', '{"question":"ABCD with AB 5 cm, BC 4 cm: after AB, which side?","wrong_answer":"CD","correct_answer":"BC"}'::jsonb, 'Draws sides as they come to hand.', 'The answer CD as a wrong option, with a reason that names the idea.', 'Follow the letters round: AB, then BC.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.GEOMET.GEOMETRICAL_CONSTRUCTION.CONSTRUCT_IRREGULAR_POLYGON.M_ANGLE_AT_WRONG_VERTEX', 'MATH.G8.GEOMET.GEOMETRICAL_CONSTRUCTION.CONSTRUCT_IRREGULAR_POLYGON', 'Constructs an angle at the wrong corner.', '{"question":"Angle ABC = 60°: at which corner?","wrong_answer":"A","correct_answer":"B"}'::jsonb, 'Reads the first letter.', 'The answer A as a wrong option, with a reason that names the idea.', 'The middle letter names the corner.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.GEOMET.GEOMETRICAL_CONSTRUCTION.CONSTRUCT_IRREGULAR_POLYGON.M_LAST_SIDE_FORCED', 'MATH.G8.GEOMET.GEOMETRICAL_CONSTRUCTION.CONSTRUCT_IRREGULAR_POLYGON', 'Joins the last two points without checking the last side length.', '{"question":"The last side should be 6 cm but measures 7 cm. What now?","wrong_answer":"leave it","correct_answer":"check the earlier steps"}'::jsonb, 'Thinks the shape is done once it closes.', 'The answer leave it as a wrong option, with a reason that names the idea.', 'Measure the last side: it checks the whole drawing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.GEOMET.GEOMETRICAL_CONSTRUCTION.CONSTRUCT_IRREGULAR_POLYGON.M_PROTRACTOR_WRONG_SCALE', 'MATH.G8.GEOMET.GEOMETRICAL_CONSTRUCTION.CONSTRUCT_IRREGULAR_POLYGON', 'Reads the wrong scale of the protractor.', '{"question":"Measure an angle of 70°.","wrong_answer":"110°","correct_answer":"70°"}'::jsonb, 'Reads the outer numbers from the wrong side.', 'The answer 110° as a wrong option, with a reason that names the idea.', 'Start from the zero on the arm you are using.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.GEOMET.GEOMETRICAL_CONSTRUCTION.CIRCUMCIRCLE.M_DIAMETER_FOR_RADIUS_CIRCUM', 'MATH.G8.GEOMET.GEOMETRICAL_CONSTRUCTION.CIRCUMCIRCLE', 'Gives the hypotenuse (the diameter) as the radius.', '{"question":"Right-angled triangle with sides 6, 8 and 10 cm. Radius of the circle through the corners?","wrong_answer":"10 cm","correct_answer":"5 cm"}'::jsonb, 'Forgets the centre is the midpoint.', 'The answer 10 cm as a wrong option, with a reason that names the idea.', 'The hypotenuse is a diameter: halve it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
