INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.GEOMET.GEOMETRICAL_CONSTRUCTION.CIRCUMCIRCLE.M_INCENTRE_CIRCUMCENTRE_SWAPPED', 'MATH.G8.GEOMET.GEOMETRICAL_CONSTRUCTION.CIRCUMCIRCLE', 'Uses angle bisectors for the circle through the corners, or perpendicular bisectors for the circle touching the sides.', '{"question":"Circle through the three corners: which lines?","wrong_answer":"angle bisectors","correct_answer":"perpendicular bisectors of the sides"}'::jsonb, 'Mixes the two constructions.', 'The answer angle bisectors as a wrong option, with a reason that names the idea.', 'Through corners: same distance from corners, so perpendicular bisectors.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.GEOMET.GEOMETRICAL_CONSTRUCTION.CIRCUMCIRCLE.M_MEDIANS_FOR_CENTRE', 'MATH.G8.GEOMET.GEOMETRICAL_CONSTRUCTION.CIRCUMCIRCLE', 'Uses the lines from corners to midpoints (medians) to find the centre.', '{"question":"Circle through the corners: centre?","wrong_answer":"where the medians meet","correct_answer":"where the perpendicular bisectors meet"}'::jsonb, 'Thinks any "middle" point works.', 'The answer where the medians meet as a wrong option, with a reason that names the idea.', 'That point balances the triangle but is not the same distance from the corners.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.GEOMET.GEOMETRICAL_CONSTRUCTION.CIRCUMCIRCLE.M_BISECTOR_THROUGH_CORNER', 'MATH.G8.GEOMET.GEOMETRICAL_CONSTRUCTION.CIRCUMCIRCLE', 'Believes a perpendicular bisector passes through a corner.', '{"question":"Where does the perpendicular bisector of AB cross AB?","wrong_answer":"at A","correct_answer":"at the midpoint of AB"}'::jsonb, 'Mixes it with a line from a corner.', 'The answer at A as a wrong option, with a reason that names the idea.', 'It crosses the side at its middle, at a right angle.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.GEOMET.GEOMETRICAL_CONSTRUCTION.CIRCUMCIRCLE.M_BISECTORS_MAKE_ANGLES_EQUAL', 'MATH.G8.GEOMET.GEOMETRICAL_CONSTRUCTION.CIRCUMCIRCLE', 'Believes drawing the bisectors makes the triangle''s angles equal.', '{"question":"Why does the construction work?","wrong_answer":"it makes every angle equal","correct_answer":"points on a bisector are the same distance from both ends"}'::jsonb, 'Thinks constructions change the triangle.', 'The answer it makes every angle equal as a wrong option, with a reason that names the idea.', 'Lines drawn do not change the triangle.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.GEOMET.GEOMETRICAL_CONSTRUCTION.CIRCUMCIRCLE.M_CONSTRUCTION_FOR_AREA', 'MATH.G8.GEOMET.GEOMETRICAL_CONSTRUCTION.CIRCUMCIRCLE', 'Believes the perpendicular bisectors are drawn to find the area.', '{"question":"Why bisect two sides?","wrong_answer":"to find the area","correct_answer":"to find the centre of the circle"}'::jsonb, 'Links lines in a triangle with area.', 'The answer to find the area as a wrong option, with a reason that names the idea.', 'Area uses base and height; the bisectors find the centre.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.GEOMET.GEOMETRICAL_CONSTRUCTION.INCIRCLE.M_INCIRCLE_RADIUS_TO_CORNER', 'MATH.G8.GEOMET.GEOMETRICAL_CONSTRUCTION.INCIRCLE', 'Takes the distance from the centre to a corner as the radius of the circle touching the sides.', '{"question":"The circle touching the sides: its radius is from the centre to?","wrong_answer":"a corner","correct_answer":"a side, at a right angle"}'::jsonb, 'Uses the circumcircle radius.', 'The answer a corner as a wrong option, with a reason that names the idea.', 'It touches the sides: measure to a side.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.GEOMET.GEOMETRICAL_CONSTRUCTION.INCIRCLE.M_INCIRCLE_FROM_SIDE_MIDPOINTS', 'MATH.G8.GEOMET.GEOMETRICAL_CONSTRUCTION.INCIRCLE', 'Draws the circle through the midpoints of the sides as the circle touching the sides.', '{"question":"Does the circle touching the sides always pass through their midpoints?","wrong_answer":"Yes","correct_answer":"No, only in an equilateral triangle"}'::jsonb, 'Thinks "touch" means at the middle.', 'The answer Yes as a wrong option, with a reason that names the idea.', 'It touches each side at the foot of the perpendicular from the centre.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.GEOMET.GEOMETRICAL_CONSTRUCTION.INCIRCLE.M_INCIRCLE_RADIUS_NOT_PERPENDICULAR', 'MATH.G8.GEOMET.GEOMETRICAL_CONSTRUCTION.INCIRCLE', 'Measures the radius along a slant line to a side.', '{"question":"How is the radius of the circle touching the sides measured?","wrong_answer":"any line to a side","correct_answer":"the perpendicular to a side"}'::jsonb, 'Does not see the shortest distance is perpendicular.', 'The answer any line to a side as a wrong option, with a reason that names the idea.', 'Construct the perpendicular from the centre to a side.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.GEOMET.GEOMETRICAL_CONSTRUCTION.INCIRCLE.M_ONE_BISECTOR_ENOUGH', 'MATH.G8.GEOMET.GEOMETRICAL_CONSTRUCTION.INCIRCLE', 'Believes one angle bisector gives the centre.', '{"question":"How many angle bisectors are needed to find the centre?","wrong_answer":"one","correct_answer":"two (they meet at the centre)"}'::jsonb, 'Thinks the centre is on one line.', 'The answer one as a wrong option, with a reason that names the idea.', 'One line holds many points; two lines meet at one.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
