INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.GEOMET.SCALE_DRAWING.REPRESENT_TO_SCALE.M_SCALE_SUBTRACTED_MAP', 'MATH.G8.GEOMET.SCALE_DRAWING.REPRESENT_TO_SCALE', 'Takes the scale away from the real length.', '{"question":"1 cm to 5 m. A 20 m wall?","wrong_answer":"15 cm","correct_answer":"4 cm"}'::jsonb, 'Tries an operation without a reason.', 'The answer 15 cm as a wrong option, with a reason that names the idea.', 'How many 5 m lengths fit in 20 m?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
