INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.GEOMET.SCALE_DRAWING.ACTUAL_TO_SCALE.M_REAL_GIVEN_FOR_MAP', 'MATH.G8.GEOMET.SCALE_DRAWING.ACTUAL_TO_SCALE', 'Gives the real length as the map length.', '{"question":"1 cm to 4 m. 24 m on the map?","wrong_answer":"24 cm","correct_answer":"6 cm"}'::jsonb, 'Forgets to scale down.', 'The answer 24 cm as a wrong option, with a reason that names the idea.', 'The map shows it much shorter.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.GEOMET.SCALE_DRAWING.ACTUAL_TO_SCALE.M_UNITS_NOT_MATCHED_MAP', 'MATH.G8.GEOMET.SCALE_DRAWING.ACTUAL_TO_SCALE', 'Divides a real length in km by a scale in m.', '{"question":"1 cm to 500 m. A road of 3 km on the map?","wrong_answer":"0.006 cm","correct_answer":"6 cm"}'::jsonb, 'Does not change to the same unit.', 'The answer 0.006 cm as a wrong option, with a reason that names the idea.', '3 km = 3,000 m; 3,000 ÷ 500.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.GEOMET.SCALE_DRAWING.SCALE_TO_ACTUAL.M_MAP_DIFFERENCE_NOT_SCALED', 'MATH.G8.GEOMET.SCALE_DRAWING.SCALE_TO_ACTUAL', 'Gives the difference on the plan, not in real life.', '{"question":"1 cm to 3 m. Hall 8 cm, classroom 5 cm. How much longer is the real hall?","wrong_answer":"3","correct_answer":"9 m"}'::jsonb, 'Forgets to scale the difference.', 'The answer 3 as a wrong option, with a reason that names the idea.', 'Multiply the difference by 3 m.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.GEOMET.SCALE_DRAWING.SCALE_TO_ACTUAL.M_ONE_LENGTH_FOR_DIFFERENCE', 'MATH.G8.GEOMET.SCALE_DRAWING.SCALE_TO_ACTUAL', 'Gives one real length when a difference is asked.', '{"question":"1 cm to 3 m. Hall 8 cm, classroom 5 cm. How much longer?","wrong_answer":"24 m","correct_answer":"9 m"}'::jsonb, 'Stops at the hall.', 'The answer 24 m as a wrong option, with a reason that names the idea.', 'Longer means subtract.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.GEOMET.SCALE_DRAWING.SCALE_TO_ACTUAL.M_SUM_FOR_DIFFERENCE', 'MATH.G8.GEOMET.SCALE_DRAWING.SCALE_TO_ACTUAL', 'Adds the lengths when the difference is asked.', '{"question":"Hall 8 cm, classroom 5 cm at 1 cm to 3 m. How much longer?","wrong_answer":"39 m","correct_answer":"9 m"}'::jsonb, 'Combines the two lengths.', 'The answer 39 m as a wrong option, with a reason that names the idea.', 'Difference: subtract.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
