INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.GEOMET.SCALE_DRAWING.SCALE_TO_ACTUAL.M_UNIT_CHANGED_NEEDLESSLY', 'MATH.G8.GEOMET.SCALE_DRAWING.SCALE_TO_ACTUAL', 'Changes the answer to another unit when the scale already gives the one asked.', '{"question":"1 cm to 2 m. 7.5 cm on the plan, in metres?","wrong_answer":"1,500","correct_answer":"15 m"}'::jsonb, 'Thinks a unit change is always needed.', 'The answer 1,500 as a wrong option, with a reason that names the idea.', 'The scale already gives metres.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.GEOMET.SCALE_DRAWING.STATEMENT_SCALE.M_WHOLE_REAL_FOR_ONE_CM', 'MATH.G8.GEOMET.SCALE_DRAWING.STATEMENT_SCALE', 'Uses the whole real distance as what 1 cm stands for.', '{"question":"6 cm on the map for 30 km. Scale statement?","wrong_answer":"1 cm represents 30 km","correct_answer":"1 cm represents 5 km"}'::jsonb, 'Forgets to share.', 'The answer 1 cm represents 30 km as a wrong option, with a reason that names the idea.', 'Divide 30 km by 6.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.GEOMET.SCALE_DRAWING.STATEMENT_SCALE.M_STATEMENT_NOT_FOR_ONE_CM', 'MATH.G8.GEOMET.SCALE_DRAWING.STATEMENT_SCALE', 'Writes the statement for the map length instead of 1 cm.', '{"question":"6 cm for 30 km. Scale statement?","wrong_answer":"6 cm represents 5 km","correct_answer":"1 cm represents 5 km"}'::jsonb, 'Mixes the two numbers.', 'The answer 6 cm represents 5 km as a wrong option, with a reason that names the idea.', 'A statement scale is for 1 cm.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
