INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.GEOMET.SCALE_DRAWING.STATEMENT_SCALE.M_STATEMENT_READ_BACKWARDS', 'MATH.G8.GEOMET.SCALE_DRAWING.STATEMENT_SCALE', 'Reads "1 cm represents 5 km" as 5 cm for 1 km.', '{"question":"1 cm represents 5 km. How far is 3 cm?","wrong_answer":"0.6 km","correct_answer":"15 km"}'::jsonb, 'Reverses the statement.', 'The answer 0.6 km as a wrong option, with a reason that names the idea.', 'Each centimetre is 5 km: 3 × 5.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G8.GEOMET.SCALE_DRAWING.RATIO_SCALE.M_RATIO_CM_NOT_CONVERTED', 'MATH.G8.GEOMET.SCALE_DRAWING.RATIO_SCALE', 'Gives the ratio number in centimetres when km or m is asked.', '{"question":"1 : 500,000. 1 cm stands for how many km?","wrong_answer":"500,000","correct_answer":"5"}'::jsonb, 'Forgets both numbers are in cm.', 'The answer 500,000 as a wrong option, with a reason that names the idea.', 'Divide by 100,000 for km.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
